/* 6 điểm ngữ pháp C1, gắn vào GRAMMAR, GRAMMAR_BANK, GRAMMAR_THEORY, GRAMMAR_GX và vào các chặng tương ứng. Nạp sau content-grammar3.js. */
(function () {
  const NEW = [{"id":"complex-noun-phrases","lvl":"C1","title":"Complex noun phrases","vi":"Cụm danh từ phức","exams":["CEFR","IELTS","VSTEP"],"form":"Tiền bổ nghĩa: determiner + (trạng từ) + tính từ/V-ed + danh từ ghép + NOUN\nHậu bổ nghĩa: NOUN + of-phrase / giới từ / mệnh đề quan hệ / to V / V-ing / V-ed","use":"Dùng trong văn viết học thuật và trang trọng để dồn nhiều thông tin vào một cụm danh từ thay vì nhiều mệnh đề rời. Giúp câu văn gọn, chính xác và có tính khách quan.","ex":[["A number of recently introduced, highly effective measures reduced waiting times.","Một số biện pháp mới được áp dụng gần đây và rất hiệu quả đã rút ngắn thời gian chờ."],["The decision to postpone the trial surprised the research team.","Quyết định hoãn thử nghiệm đã khiến nhóm nghiên cứu bất ngờ."],["The patients treated last year showed steady improvement.","Những bệnh nhân được điều trị năm ngoái cho thấy sự cải thiện đều đặn."],["Hospital staff shortage remains the main obstacle to reform.","Tình trạng thiếu nhân viên bệnh viện vẫn là trở ngại chính đối với cải cách."]],"err":[["The measures recently introduced were effective.","The recently introduced measures were effective.","Tính từ/V-ed có trạng từ đứng trước thì đặt trước danh từ: “recently introduced measures”. Đặt sau danh từ cần cả cụm: “measures that were recently introduced”."],["The decision postponing the trial was criticised.","The decision to postpone the trial was criticised.","Sau danh từ “decision” dùng to-infinitive để chỉ nội dung quyết định, không dùng V-ing."],["Staffs shortage is serious.","Staff shortage is serious.","Danh từ đứng trước trong danh từ ghép thường ở dạng số ít: “staff shortage”, “job satisfaction”."]],"quiz":[["The committee welcomed the ___ to extend the pilot scheme.",["deciding","decision","decided","decisively"],1,"Danh từ “decision” đi với to-infinitive để nêu nội dung quyết định, và sau mạo từ “the” cần một danh từ.",{"deciding":"Dạng V-ing không đứng được sau “the” rồi mới nối với “to extend” để chỉ nội dung quyết định.","decided":"Dạng V-ed là động từ hoặc tính từ, không làm danh từ trung tâm sau “the” trong câu này.","decisively":"Trạng từ không thể đứng sau mạo từ “the” và trước “to extend” như một danh từ."}],["The nurses ___ the night shift reported a rise in complaints.",["worked","who working","to be working","working"],3,"Rút gọn mệnh đề quan hệ chủ động bằng V-ing sau danh từ: “nurses working the night shift”.",{"worked":"V-ed mang nghĩa bị động, không hợp với y tá là người thực hiện ca đêm.","who working":"“who working” thiếu trợ động từ, mệnh đề quan hệ này không hoàn chỉnh về ngữ pháp.","to be working":"To-infinitive diễn tả mục đích hoặc tương lai, không nêu việc họ đang làm ca đêm."}],["Researchers criticised the ___ methods used in the survey.",["designed poorly","design poorly","poorly designed","poorly design"],2,"Trạng từ + V-ed đứng trước danh từ làm tiền bổ nghĩa: “poorly designed methods”, theo sau là “methods”.",{"designed poorly":"Trạng từ đặt sau V-ed chỉ hợp khi cụm đứng sau danh từ, còn ở đây cụm phải đứng trước “methods”.","design poorly":"Dạng nguyên thể kèm trạng từ không đứng làm bổ nghĩa trước danh từ “methods”.","poorly design":"“design” là nguyên thể, không làm tính từ bổ nghĩa; cần dạng V-ed “designed” trước “methods”."}],["Rising ___ costs have forced several clinics to close.",["staff","staffs","staffing's","staffed"],0,"Danh từ ghép dùng danh từ số ít không thêm -s làm bổ nghĩa: “staff costs”; “staff” còn là danh từ tập hợp.",{"staffs":"“staffs” thêm -s không cần thiết, danh từ đứng trước trong danh từ ghép thường không ở số nhiều.","staffing's":"Dạng sở hữu thêm “'s” làm cụm lệch chuẩn và thừa trong danh từ ghép “staff costs”.","staffed":"V-ed “staffed” là động từ bị động, không tạo nên danh từ ghép “chi phí nhân viên”."}]]},{"id":"emphasis-structures","lvl":"C1","title":"Emphasis structures","vi":"Cấu trúc nhấn mạnh","exams":["CEFR","VSTEP","IELTS"],"form":"Trợ động từ nhấn mạnh: S + do/does/did + V (I did tell you).\nĐại từ phản thân nhấn mạnh: the director herself / S + V + O + myself.\nMệnh đề What/All: What I need is + N/V; All I want is (to) + V.","use":"Dùng để làm nổi bật một ý, sửa lại hiểu lầm hoặc bộc lộ cảm xúc mạnh trong nói và viết trang trọng. Khi nói thì nhấn giọng; khi viết dùng cấu trúc, dấu phẩy hoặc chữ nghiêng.","ex":[["I did warn you that the roads would be icy.","Tôi đã cảnh báo bạn rằng đường sẽ đóng băng mà."],["The director herself signed every letter.","Chính giám đốc đã ký từng lá thư."],["What I need is a few days of complete rest.","Điều tôi cần là vài ngày nghỉ ngơi hoàn toàn."],["The results were by no means conclusive.","Kết quả hoàn toàn không mang tính kết luận."]],"err":[["I did told her about the delay.","I did tell her about the delay.","Sau did nhấn mạnh phải dùng động từ nguyên mẫu, không chia quá khứ lần nữa."],["What I want it is a quiet evening.","What I want is a quiet evening.","Trong mệnh đề What, không thêm đại từ “it” trước động từ be."],["It was such a lovely day that we stayed out.","It was such a lovely day that we stayed out. (hoặc: It was so lovely a day...)","Such đi với a + tính từ + danh từ; so đi với tính từ. Đừng trộn hai cấu trúc."]],"quiz":[["You keep saying I forgot the files, but I ___ bring them; they are in the blue folder.",["did","do","did bring","done"],0,"Phản bác hiểu lầm về quá khứ dùng did + V nguyên mẫu; “forgot” cho thấy cần thì quá khứ.",{"do":"Câu kể về hành động đã xảy ra trong quá khứ nên “do” ở hiện tại không khớp thì với “forgot”.","did bring":"Sau chỗ trống đã có sẵn “bring”, nên thêm “bring” nữa sẽ lặp động từ.","done":"“Done” là quá khứ phân từ, không thể đứng trước động từ nguyên mẫu “bring”."}],["The head of department ___ will chair the interview panel this year.",["her","herself","she","hers"],1,"Đại từ phản thân đặt sau danh từ chỉ người nhấn mạnh chính người đó; chủ ngữ là nữ nên dùng herself.",{"her":"“Her” là đại từ sở hữu hoặc tân ngữ, không dùng để nhấn mạnh chủ ngữ “the head of department”.","she":"“She” lặp lại chủ ngữ nên câu thừa và không có nghĩa nhấn mạnh chính người đó.","hers":"“Hers” là đại từ sở hữu độc lập, không đứng ngay sau danh từ làm từ nhấn mạnh."}],["It was ___ a long wait that several patients simply gave up and went home.",["so","very","such","too"],2,"Such + a + tính từ + danh từ + that diễn tả mức độ dẫn đến kết quả; “that several patients gave up” là kết quả.",{"so":"“So” đi với tính từ, còn ở đây sau chỗ trống là “a long wait”, tức a + tính từ + danh từ.","very":"“Very” không tạo cấu trúc kết quả với “that”, và không đứng trước mạo từ “a”.","too":"“Too” cần tính từ và mang nghĩa quá mức, không kết hợp với “a long wait that...”."}],["What the students most need ___ more practice in speaking.",["are","be","it is","is"],3,"Mệnh đề What… + is + bổ ngữ; “more practice” là danh từ không đếm được, nên động từ là “is”.",{"are":"Mệnh đề What làm chủ ngữ coi là một khối số ít, và bổ ngữ “more practice” không đếm được.","be":"Động từ chính của câu cần chia thì hiện tại, không để ở nguyên mẫu “be”.","it is":"Không được thêm “it” sau mệnh đề What; câu sẽ có hai chủ ngữ."}]]},{"id":"modals-advanced","lvl":"C1","title":"Advanced modal verbs","vi":"Động từ khuyết thiếu nâng cao","exams":["CEFR","VSTEP","IELTS"],"form":"Modal + have been + V-ing (should have been waiting). Modal + be + V-ing (may be working).\nneedn't have + V3 (đã làm mà không cần). be to + V (sắp xếp/mệnh lệnh).\nwill + V (thói quen, đặc điểm); would + V (thói quen quá khứ).","use":"Dùng để nói về hành động đang diễn ra hoặc kéo dài với độ chắc chắn khác nhau, để phê bình việc đã làm, để diễn đạt quy định trang trọng, thói quen và giả định.","ex":[["You should have been waiting at the entrance, not in the café.","Lẽ ra bạn phải đang đợi ở cửa vào, chứ không phải trong quán cà phê."],["We needn't have hurried; the clinic opened late.","Lẽ ra chúng tôi không cần vội; phòng khám mở cửa muộn."],["The minister is to visit the new hospital on Friday.","Bộ trưởng sẽ đến thăm bệnh viện mới vào thứ Sáu."],["My supervisor will sit for hours reading a single paper.","Giáo viên hướng dẫn của tôi có thể ngồi hàng giờ chỉ để đọc một bài báo."]],"err":[["She needn't to have come so early.","She needn't have come so early.","Sau needn't dùng động từ nguyên mẫu không to: needn't have + V3."],["He can't be work at this hour.","He can't be working at this hour.","Để nói về hành động đang diễn ra, dùng modal + be + V-ing, không dùng động từ nguyên mẫu."],["You might as well to stay here.","You might as well stay here.","Might as well đi với động từ nguyên mẫu không to."]],"quiz":[["You were supposed to meet us at eight. You ___ outside the lecture hall, but you were still at home.",["should have been waiting","should be waiting","must have been waiting","might be waiting"],0,"Phê bình việc lẽ ra đang diễn ra trong quá khứ dùng should have been + V-ing; mệnh đề “but you were still at home” cho thấy bạn đã không đợi.",{"should be waiting":"Should be waiting nói về hiện tại, trong khi câu nói về lúc tám giờ trong quá khứ nên không khớp thời gian.","must have been waiting":"Must have been waiting là suy luận rằng bạn đã đợi, mâu thuẫn với vế sau nói bạn vẫn ở nhà.","might be waiting":"Might be waiting chỉ khả năng ở hiện tại, không diễn đạt được ý trách móc về việc lẽ ra phải làm."}],["It's ten at night and the lab light is still on, so Dr Hale ___ on his report.",["must have worked","ought to work","must be working","can't have been working"],2,"Suy luận chắc chắn về hành động đang diễn ra ngay bây giờ dùng must be + V-ing; “still on” cho thấy việc đang tiếp diễn.",{"must have worked":"Must have worked nói về hành động đã hoàn tất trong quá khứ, trong khi đèn vẫn đang sáng ở hiện tại.","ought to work":"Ought to work là lời khuyên, không phải suy luận từ bằng chứng là đèn còn sáng.","can't have been working":"Can't have been working phủ định việc đã xảy ra trong quá khứ, trái với bằng chứng đèn vẫn sáng."}],["We took a taxi, but the meeting started late. We ___ hurried.",["needn't","needn't have","didn't need","mustn't have"],1,"Needn't have + V3 nói hành động đã xảy ra nhưng không cần thiết; “took a taxi” và “started late” cho thấy sự vội vã là thừa.",{"needn't":"Needn't hurried sai cấu trúc vì sau needn't phải là động từ nguyên mẫu, ở đây lại là quá khứ phân từ.","didn't need":"Didn't need hurried sai ngữ pháp vì didn't need cần đi với to V hoặc động từ nguyên mẫu, không phải dạng quá khứ.","mustn't have":"Mustn't have hurried là suy luận về điều không thể, nghĩa không hợp với việc đã vội vì cuộc họp bắt đầu muộn."}],["According to the notice, the new regulations ___ come into force on 1 January.",["are going","are able to","are about","are to"],3,"Be to + V diễn đạt sắp xếp hoặc kế hoạch chính thức; trước “come into force” cần are to, và “according to the notice” cho thấy văn phong trang trọng.",{"are going":"Are going cần to để thành are going to come, nên ở đây thiếu to và câu không thành cấu trúc đúng.","are able to":"Are able to nghĩa là có khả năng, không phải một sự sắp xếp, và không hợp với quy định có hiệu lực.","are about":"Are about cần to để thành are about to come, vì vậy thiếu to nên sai cấu trúc trong câu này."}]]},{"id":"passive-advanced","lvl":"C1","title":"Advanced passive structures","vi":"Câu bị động nâng cao","exams":["CEFR","VSTEP","IELTS"],"form":"Modal + be + V3: must be done. Modal perfect: ought to have been done.\nTo be + V3 / being + V3 / to have been + V3. Have/get + O + V3.\nGive/send/offer/show: He was given a prize. Impersonal: It is expected that + clause.","use":"Dùng trong văn phong trang trọng, học thuật để tập trung vào hành động hoặc đối tượng chịu tác động thay vì người thực hiện. Thường nêu tác nhân (by...) chỉ khi đó là thông tin mới.","ex":[["The results must be checked before they are published.","Kết quả phải được kiểm tra trước khi công bố."],["She hates being asked to repeat herself.","Cô ấy ghét bị yêu cầu nhắc lại điều mình đã nói."],["The elderly patients were well looked after by the nursing staff.","Các bệnh nhân cao tuổi được nhân viên điều dưỡng chăm sóc chu đáo."],["I had my laptop repaired last week.","Tuần trước tôi đã nhờ người sửa máy tính xách tay."]],"err":[["The problem must be dealt it with immediately.","The problem must be dealt with immediately.","Động từ giới từ giữ nguyên giới từ khi bị động: “deal with” thành “be dealt with”; không thêm tân ngữ “it”."],["The prize was given the winner by the mayor.","The prize was given to the winner by the mayor.","Khi tân ngữ trực tiếp làm chủ ngữ, tân ngữ gián tiếp cần “to”: “was given to the winner”."],["She doesn't like being to tell what to do.","She doesn't like being told what to do.","Sau giới từ/động từ yêu thích dùng “being + V3”, không dùng “being to + V”."]],"quiz":[["The final report ___ to the board before the end of the month.",["must be submitted","must submit","must be submit","must been submitted"],0,"Động từ khuyết thiếu + be + V3 tạo bị động; chủ ngữ “report” là vật chịu tác động nên cần dạng bị động.",{"must submit":"Chủ ngữ “report” là vật không thể tự nộp nên cần bị động; câu này thiếu “be” và dạng V3.","must be submit":"Sau “be” trong câu bị động phải dùng quá khứ phân từ “submitted”, không dùng nguyên mẫu.","must been submitted":"Sau động từ khuyết thiếu phải dùng “be”, không dùng “been” vì “been” chỉ đi với “have”."}],["The patients ought to ___ about the risks before the operation.",["be warned","have been warned","have warned","having been warned"],1,"“Ought to have been + V3” diễn tả việc lẽ ra phải được làm trong quá khứ; “before the operation” là dấu hiệu quá khứ.",{"be warned":"“Be warned” chỉ việc cần làm từ bây giờ, trong khi “before the operation” nói về việc đã lẽ ra xảy ra.","have warned":"Dạng chủ động nghĩa là bệnh nhân đã đi cảnh báo người khác, trái với nghĩa của câu.","having been warned":"Sau “ought to” phải dùng nguyên mẫu không “to” đã chia, không dùng dạng danh động từ “having been”."}],["She hates ___ to repeat the same instructions every morning.",["asking","to ask","being asked","been asked"],2,"Sau “hate” dùng danh động từ bị động “being + V3” khi chủ ngữ nhận hành động; ở đây cô ấy bị yêu cầu lặp lại hướng dẫn.",{"asking":"Dạng chủ động nghĩa là cô ấy là người đi hỏi người khác, trái với ý cô bị yêu cầu.","to ask":"Nguyên mẫu chủ động cũng có nghĩa cô ấy đi hỏi, không phải bị yêu cầu lặp lại.","been asked":"Sau “hates” cần danh động từ “being”, không dùng quá khứ phân từ “been asked” đứng một mình."}],["The meeting has been ___ until the director returns from Hanoi.",["put away","put out","put up","put off"],3,"“Put off” nghĩa là hoãn lại; dấu hiệu là “until the director returns” cho thấy cuộc họp bị dời lại.",{"put away":"“Put away” nghĩa là cất đi, không có nghĩa hoãn một cuộc họp.","put out":"“Put out” nghĩa là dập tắt hoặc đưa ra, không hợp với việc hoãn họp đến khi giám đốc về.","put up":"“Put up” nghĩa là dựng lên hoặc cho ở nhờ, không mang nghĩa hoãn lại."}]]},{"id":"prepositional-phrases","lvl":"C1","title":"Prepositional phrases and fixed expressions","vi":"Cụm giới từ và thành ngữ cố định","exams":["CEFR","VSTEP","IELTS"],"form":"Giới từ + danh từ không mạo từ: in hospital, by car, on foot, at risk, under pressure.\nGiới từ phức: according to, due to, in spite of, as a result of, instead of + danh từ / V-ing.\nDanh từ / tính từ + giới từ: a rise in, a solution to, aware of, prone to.","use":"Dùng để diễn đạt chính xác, trang trọng trong văn viết học thuật và công việc, vì nhiều cụm giới từ đã cố định và không thể tự thay giới từ hay thêm mạo từ.","ex":[["The patient has been in hospital for three weeks.","Bệnh nhân đã nằm viện được ba tuần."],["Owing to the strike, all flights were cancelled.","Do cuộc đình công, mọi chuyến bay đều bị hủy."],["There has been a sharp rise in the cost of housing.","Chi phí nhà ở đã tăng mạnh."],["In the event of fire, leave the building by the nearest exit.","Trong trường hợp hỏa hoạn, hãy rời tòa nhà bằng lối thoát gần nhất."]],"err":[["The nurse is in charge for the night shift.","The nurse is in charge of the night shift.","Cụm cố định là “in charge of”, không dùng “for”."],["Despite of the rain, we continued the survey.","In spite of the rain, we continued the survey. / Despite the rain, we continued the survey.","“Despite” không đi với “of”; chỉ “in spite of” mới có “of”."],["There was an increase on the number of applicants.","There was an increase in the number of applicants.","Sau “an increase / a rise” nói về cái gì tăng thì dùng “in”."]],"quiz":[["After the accident, the driver spent a week ___ hospital before he could go home.",["in","at","on","to"],0,"Nằm viện với tư cách bệnh nhân dùng “in hospital” không mạo từ; “spent a week” cho thấy trạng thái ở lại điều trị.",{"at":"“At hospital” không dùng khi nói về bệnh nhân nằm viện; bệnh nhân phải dùng “in hospital” không mạo từ.","on":"“On hospital” không tồn tại, giới từ này không đi với nơi điều trị bệnh nhân nằm lại.","to":"“To” chỉ hướng đi tới, không diễn tả trạng thái đang nằm viện suốt một tuần."}],["The factory was closed ___ the failure of the safety inspection.",["in spite of","as a result of","instead of","apart from"],1,"Cần giới từ phức chỉ nguyên nhân – kết quả; “the failure of the safety inspection” là nguyên nhân nên dùng “as a result of”.",{"in spite of":"“In spite of” chỉ sự nhượng bộ; việc nhà máy đóng cửa là hậu quả, không phải điều trái với kỳ vọng.","instead of":"“Instead of” nghĩa là thay vì, không diễn đạt quan hệ nguyên nhân với việc kiểm tra an toàn thất bại.","apart from":"“Apart from” nghĩa là ngoài ra hoặc trừ ra, không chỉ nguyên nhân dẫn tới việc đóng cửa."}],["There has been a steady rise ___ the number of students studying abroad.",["of","on","in","at"],2,"“A rise in + danh từ” nêu thứ đang tăng; “the number of students” là đối tượng thay đổi trong câu này.",{"of":"Sau “a rise” để nói cái gì tăng phải dùng “in”; “of” chỉ dùng cho mức tăng như “a rise of 5%”.","on":"“A rise on” không phải kết hợp đúng; danh từ rise đi với “in” khi nêu đối tượng thay đổi.","at":"“At” không đi sau danh từ rise; nó thường chỉ điểm hoặc mức, không chỉ đối tượng tăng."}],["Our train was delayed, but we reached the airport ___ time to check in.",["on","at","by","in"],3,"“In time to + V” nghĩa là kịp làm gì; “delayed” và “to check in” cho thấy ý kịp lúc chứ không phải đúng lịch.",{"on":"“On time” nghĩa là đúng giờ theo lịch; còn “time to check in” cần “in time” (kịp để làm gì).","at":"“At time” không là cụm cố định; “at times” mới có nghĩa thỉnh thoảng nhưng không hợp câu.","by":"“By time” không tồn tại; cụm đúng nghĩa là kịp để làm gì là “in time to + V”."}]]},{"id":"verb-patterns-advanced","lvl":"C1","title":"Advanced verb patterns","vi":"Cấu trúc động từ nâng cao","exams":["CEFR","VSTEP","IELTS"],"form":"remember/forget/stop/try/regret + V-ing (việc đã xảy ra) hoặc to V (việc sắp làm).\nperceive/make/let/help + O + V; need/deserve + V-ing / to be V-ed.\nPassive: to be told, being asked, to have been done.","use":"Dùng để chọn đúng dạng động từ theo sau (V-ing, to V, V nguyên mẫu) khi nghĩa thay đổi hoặc khi động từ chính đòi một mẫu cố định. Rất quan trọng trong văn viết học thuật và phần thi nói, viết.","ex":[["I'll never forget meeting the Prime Minister at the conference.","Tôi sẽ không bao giờ quên việc đã gặp Thủ tướng tại hội nghị."],["The nurse stopped to check the patient's chart before leaving.","Y tá dừng lại để kiểm tra bệnh án của bệnh nhân trước khi rời đi."],["The old bridge needs repairing before winter.","Cây cầu cũ cần được sửa chữa trước mùa đông."],["She deserves to be promoted after such hard work.","Cô ấy xứng đáng được thăng chức sau bao nhiêu nỗ lực."]],"err":[["I regret to say that I lied to you last year.","I regret saying that I lied to you last year.","Việc nói đã xảy ra rồi nên dùng “regret + V-ing”; “regret to say” chỉ dùng khi thông báo tin xấu ngay lúc nói."],["We saw the thief to run away.","We saw the thief run away.","Sau động từ tri giác + tân ngữ dùng V nguyên mẫu (không “to”) hoặc V-ing."],["The printer needs to repair.","The printer needs repairing. / The printer needs to be repaired.","Chủ ngữ là vật được sửa nên dùng “need + V-ing” hoặc “need to be V-ed”."]],"quiz":[["I'll never forget ___ the sea for the first time; it was breathtaking.",["seeing","to see","see","to have seen"],0,"“Forget + V-ing” nói về việc đã xảy ra mà mình nhớ mãi; “it was breathtaking” cho thấy đây là một kỷ niệm đã qua.",{"to see":"“Forget to see” nghĩa là quên không làm; câu này nói về ký ức đã xảy ra nên cần V-ing.","see":"Sau forget không dùng V nguyên mẫu trần, câu cần dạng V-ing để nói về kỷ niệm trong quá khứ.","to have seen":"Dạng hoàn thành sau forget nghe không tự nhiên ở đây; V-ing đơn giản đã diễn tả ký ức đủ rõ."}],["Please remember ___ the lights before you leave the lab tonight.",["switching off","to switch off","switch off","having switched off"],1,"“Remember + to V” là nhớ để làm việc cần làm; “before you leave” cho thấy việc tắt đèn còn ở phía trước.",{"switching off":"“Remember + V-ing” là nhớ việc đã làm, còn ở đây việc tắt đèn chưa xảy ra.","switch off":"Sau remember không dùng V nguyên mẫu trần; cần “to V” hoặc V-ing tùy nghĩa của câu.","having switched off":"Dạng hoàn thành chỉ việc đã xong, trong khi lời nhắc nói về việc sẽ làm trước khi rời phòng."}],["He did not stop at the first degree; he went on ___ a doctorate and then a professorship.",["earning","earn","to earn","to earning"],2,"“Go on + to V” nghĩa là sau đó làm tiếp một việc khác; bằng tiến sĩ và giáo sư là các bước mới sau bằng đầu tiên.",{"earning":"“Go on + V-ing” là tiếp tục làm cùng một việc, nhưng ở đây anh ấy chuyển sang việc mới.","earn":"Sau go on không dùng V nguyên mẫu trần, cần dạng “to V” hoặc V-ing theo nghĩa.","to earning":"Sau “go on to” phải là động từ nguyên mẫu; “to earning” không tạo thành cấu trúc đúng."}],["I'm so tired of the noise. Will you please stop ___ that drum?",["to play","play","to be playing","playing"],3,"“Stop + V-ing” là ngừng hẳn hành động đang làm; người nói đang phàn nàn về tiếng ồn nên muốn tiếng trống dừng lại.",{"to play":"“Stop to play” nghĩa là dừng lại để chơi, trái hẳn với ý muốn người kia ngừng chơi.","play":"Sau stop không dùng V nguyên mẫu trần; cần V-ing để diễn tả hành động bị ngừng.","to be playing":"Dạng này không đi sau stop và làm câu nặng nề, không diễn tả việc ngừng một hành động."}]]}];
  const BANK = {"complex-noun-phrases":"c|The committee welcomed the ___ to extend the pilot scheme.|deciding / decision / decided / decisively|1|Danh từ “decision” đi với to-infinitive để nêu nội dung quyết định, và sau mạo từ “the” cần một danh từ.|deciding=>Dạng V-ing không đứng được sau “the” rồi mới nối với “to extend” để chỉ nội dung quyết định.;;decided=>Dạng V-ed là động từ hoặc tính từ, không làm danh từ trung tâm sau “the” trong câu này.;;decisively=>Trạng từ không thể đứng sau mạo từ “the” và trước “to extend” như một danh từ.\nc|The nurses ___ the night shift reported a rise in complaints.|worked / who working / to be working / working|3|Rút gọn mệnh đề quan hệ chủ động bằng V-ing sau danh từ: “nurses working the night shift”.|worked=>V-ed mang nghĩa bị động, không hợp với y tá là người thực hiện ca đêm.;;who working=>“who working” thiếu trợ động từ, mệnh đề quan hệ này không hoàn chỉnh về ngữ pháp.;;to be working=>To-infinitive diễn tả mục đích hoặc tương lai, không nêu việc họ đang làm ca đêm.\nc|Researchers criticised the ___ methods used in the survey.|designed poorly / design poorly / poorly designed / poorly design|2|Trạng từ + V-ed đứng trước danh từ làm tiền bổ nghĩa: “poorly designed methods”, theo sau là “methods”.|designed poorly=>Trạng từ đặt sau V-ed chỉ hợp khi cụm đứng sau danh từ, còn ở đây cụm phải đứng trước “methods”.;;design poorly=>Dạng nguyên thể kèm trạng từ không đứng làm bổ nghĩa trước danh từ “methods”.;;poorly design=>“design” là nguyên thể, không làm tính từ bổ nghĩa; cần dạng V-ed “designed” trước “methods”.\nc|Rising ___ costs have forced several clinics to close.|staff / staffs / staffing's / staffed|0|Danh từ ghép dùng danh từ số ít không thêm -s làm bổ nghĩa: “staff costs”; “staff” còn là danh từ tập hợp.|staffs=>“staffs” thêm -s không cần thiết, danh từ đứng trước trong danh từ ghép thường không ở số nhiều.;;staffing's=>Dạng sở hữu thêm “'s” làm cụm lệch chuẩn và thừa trong danh từ ghép “staff costs”.;;staffed=>V-ed “staffed” là động từ bị động, không tạo nên danh từ ghép “chi phí nhân viên”.\nc|A report ___ last month warned of a shortage of qualified teachers.|publishing / which publishing / to publish / published|3|“A report” được công bố nên dùng V-ed bị động rút gọn: “a report published last month”.|publishing=>V-ing mang nghĩa chủ động, báo cáo không tự đi công bố bất kỳ thứ gì ở đây.;;which publishing=>“which publishing” thiếu trợ động từ nên mệnh đề quan hệ này sai ngữ pháp.;;to publish=>To-infinitive không phù hợp với mốc “last month” là việc đã xảy ra rồi.\nc|The government announced a plan ___ the number of hospital beds by 2030.|doubling / to double / doubled / double|1|Danh từ “plan” thường đi với to-infinitive để nói mục tiêu: “a plan to double the number of...”.|doubling=>Dạng V-ing sau “plan” có nghĩa kế hoạch đang thực hiện việc nhân đôi, lệch với mục tiêu tương lai “by 2030”.;;doubled=>V-ed đổi nghĩa thành kế hoạch đã bị nhân đôi, không hợp ngữ cảnh mục tiêu tới 2030.;;double=>Dạng nguyên thể không có “to” không đứng sau danh từ “plan” để nêu mục tiêu.\nx|Chọn câu đúng về hậu bổ nghĩa của danh từ|The students interviewed during the study were all over fifty. / The students interviewing during the study were all over fifty. / The interviewed students during the study they were all over fifty. / The students to interview during the study were all over fifty.|0|Sinh viên được phỏng vấn mang nghĩa bị động, nên dùng V-ed rút gọn: “students interviewed during the study”.|The students interviewing during the study were all over fifty.=>V-ing có nghĩa chủ động, sinh viên không thực hiện việc phỏng vấn trong câu này.;;The interviewed students during the study they were all over fifty.=>Câu thừa đại từ “they” làm chủ ngữ bị lặp, nên sai cấu trúc.;;The students to interview during the study were all over fifty.=>To-infinitive diễn tả việc sẽ làm, không hợp với “during the study” đã diễn ra.\nx|Chọn câu dùng danh từ + to-infinitive đúng|Her reluctance of accepting the offer surprised us. / Her reluctance to accept the offer surprised us. / Her reluctance for accept the offer surprised us. / Her reluctance accepting the offer surprised us.|1|Danh từ “reluctance” đi với to-infinitive: “reluctance to accept”.|Her reluctance of accepting the offer surprised us.=>“reluctance of” không đi với V-ing trong cách nói chuẩn này, dùng “to V”.;;Her reluctance for accept the offer surprised us.=>“for accept” dùng động từ nguyên thể sau giới từ, sai ngữ pháp.;;Her reluctance accepting the offer surprised us.=>V-ing đứng trực tiếp sau danh từ làm câu không đúng cấu trúc quen thuộc của “reluctance”.\nt|The report highlighted the urgent need ___ (improve) rural health care.|to improve|Danh từ “need” đi với to-infinitive để nêu nội dung cần thiết: “the need to improve”.\nt|The funds ___ (allocate) to the project were not enough.|allocated|Quỹ được phân bổ mang nghĩa bị động, nên dùng V-ed rút gọn: “funds allocated”.\nf|The recently introduce measures cut waiting times by a third.|introduce|introduced|Trước danh từ, bổ nghĩa bị động cần dạng V-ed: “recently introduced measures”.\no|The decision to postpone the vote disappointed many members.|Danh từ trung tâm “decision” đứng đầu, to-infinitive “to postpone the vote” bổ nghĩa ngay sau nó, rồi mới tới động từ chính.\nc|The ___ of antibiotics in farming has raised concerns among doctors.|use widespread / widely used / widespread use / wide using|2|Trước “of antibiotics” cần danh từ trung tâm “use” cùng tính từ đứng trước: “the widespread use of”.|use widespread=>Tính từ phải đứng trước danh từ “use”, không đứng sau nó trước giới từ “of”.;;widely used=>“widely used” là cụm V-ed, không làm danh từ trung tâm trước “of antibiotics”.;;wide using=>“using” là dạng V-ing, không thay cho danh từ “use” trước “of” trong cụm này.\nc|Employers value candidates with the ___ under pressure.|ability to work / ability working / ability of work / able to work|0|Cụm danh từ cần danh từ “ability” theo sau là to-infinitive: “the ability to work under pressure”.|ability working=>Danh từ “ability” đi với to-infinitive, V-ing không dùng trực tiếp sau nó theo cấu trúc này.;;ability of work=>Sau “ability of” phải là danh từ hoặc V-ing, nguyên thể “work” không đúng.;;able to work=>“able” là tính từ, không đứng sau “the” để làm danh từ trung tâm.\nc|There has been a sharp ___ in the number of students applying for nursing.|increasing / increase / increased / increasingly|1|Sau “a sharp” cần danh từ trung tâm “increase”, rồi cụm “in the number of...” bổ nghĩa.|increasing=>V-ing sau “a sharp” không làm danh từ; cần danh từ “increase” đi với “in”.;;increased=>V-ed là động từ hoặc tính từ, không đứng sau “a sharp” như danh từ trung tâm.;;increasingly=>Trạng từ không đứng sau tính từ “sharp” để thay cho một danh từ.\nc|The factors ___ the success of the programme are still debated.|contributed to / to contribute for / are contributing to / contributing to|3|Mệnh đề quan hệ chủ động rút gọn bằng V-ing sau danh từ: “factors contributing to the success”.|contributed to=>V-ed mang nghĩa bị động, nhưng các yếu tố tự góp phần tạo nên thành công nên cần V-ing.;;to contribute for=>“to contribute for” sai giới từ và nghĩa mục đích không phù hợp.;;are contributing to=>“are contributing” là một mệnh đề đầy đủ nên chồng lên động từ chính “are debated” gây sai ngữ pháp.\nc|She wrote a ___ on the effects of sleep deprivation.|short, well-researched article / well-researched, short article / short article well-researched / article short, well-researched|0|Sau mạo từ “a”, tính từ bổ nghĩa đứng trước danh từ “article”, và tính từ ngắn gọn thường đứng trước cụm V-ed.|well-researched, short article=>Trật tự đúng cần tính từ ngắn gọn đứng trước cụm “well-researched” và trước danh từ.;;short article well-researched=>Cụm “well-researched” bị đặt sau danh từ nên không tạo thành tiền bổ nghĩa đúng.;;article short, well-researched=>Cụm bổ nghĩa đứng sau “article” sẽ chồng với “a” đã đứng trước, làm câu sai.\nc|The team published a study ___ the link between diet and sleep.|explored / to explore / exploring / who explored|2|Mệnh đề quan hệ chủ động rút gọn bằng V-ing: “a study exploring the link”.|explored=>V-ed mang nghĩa bị động, nhưng nghiên cứu đang khám phá mối liên hệ nên cần V-ing.;;to explore=>To-infinitive nói mục đích sau danh từ, không hợp với ý nghiên cứu đã công bố.;;who explored=>“who” chỉ dùng cho người, còn “study” là vật.\nx|Chọn câu có cụm danh từ đúng|The proposal to build a new ward was approved. / The proposal building a new ward to be approved. / The proposal of to build a new ward was approved. / The proposal build a new ward was approved.|0|Danh từ “proposal” đi với to-infinitive để nêu nội dung đề xuất rồi mới tới động từ chính “was approved”.|The proposal building a new ward to be approved.=>Câu thiếu động từ chính vì “to be approved” không đóng vai động từ chia thì.;;The proposal of to build a new ward was approved.=>“of to build” ghép giới từ với to-infinitive nên sai ngữ pháp.;;The proposal build a new ward was approved.=>Động từ nguyên thể “build” đứng thẳng sau danh từ mà không có “to” nên sai.\nx|Chọn câu nén thông tin đúng|Doctors treated these patients need extra training. / Doctors treating these patients need extra training. / Doctors to treat these patients needs extra training. / Doctors who treating these patients need extra training.|1|Chủ ngữ là “doctors treating these patients”, V-ing chủ động bổ nghĩa cho “doctors” rồi động từ chính “need”.|Doctors treated these patients need extra training.=>V-ed mang nghĩa bị động, nhưng bác sĩ là người điều trị nên cần V-ing.;;Doctors to treat these patients needs extra training.=>“Doctors” số nhiều đi với “needs” sai hoà hợp chủ vị, và “to treat” đổi nghĩa.;;Doctors who treating these patients need extra training.=>“who treating” thiếu trợ động từ, mệnh đề quan hệ này sai.\nt|Students ___ (apply) for the scholarship must submit a reference.|applying|Sinh viên là người nộp đơn, nên dùng V-ing chủ động rút gọn: “students applying”.\nt|The need ___ (recruit) more nurses is clear to everyone.|to recruit|Danh từ “need” đi với to-infinitive nên dùng “to recruit”.\nf|The number of patients waiting for surgery have fallen sharply this year.|have|has|Danh từ trung tâm của chủ ngữ là “number” số ít, nên động từ phải là “has”.\no|A number of highly qualified candidates applied for the post.|Cụm danh từ có thứ tự: “a number of”, trạng từ “highly”, tính từ “qualified”, rồi danh từ “candidates”.","emphasis-structures":"c|You keep saying I forgot the files, but I ___ bring them; they are in the blue folder.|did / do / did bring / done|0|Phản bác hiểu lầm về quá khứ dùng did + V nguyên mẫu; “forgot” cho thấy cần thì quá khứ.|do=>Câu kể về hành động đã xảy ra trong quá khứ nên “do” ở hiện tại không khớp thì với “forgot”.;;did bring=>Sau chỗ trống đã có sẵn “bring”, nên thêm “bring” nữa sẽ lặp động từ.;;done=>“Done” là quá khứ phân từ, không thể đứng trước động từ nguyên mẫu “bring”.\nc|The head of department ___ will chair the interview panel this year.|her / herself / she / hers|1|Đại từ phản thân đặt sau danh từ chỉ người nhấn mạnh chính người đó; chủ ngữ là nữ nên dùng herself.|her=>“Her” là đại từ sở hữu hoặc tân ngữ, không dùng để nhấn mạnh chủ ngữ “the head of department”.;;she=>“She” lặp lại chủ ngữ nên câu thừa và không có nghĩa nhấn mạnh chính người đó.;;hers=>“Hers” là đại từ sở hữu độc lập, không đứng ngay sau danh từ làm từ nhấn mạnh.\nc|It was ___ a long wait that several patients simply gave up and went home.|so / very / such / too|2|Such + a + tính từ + danh từ + that diễn tả mức độ dẫn đến kết quả; “that several patients gave up” là kết quả.|so=>“So” đi với tính từ, còn ở đây sau chỗ trống là “a long wait”, tức a + tính từ + danh từ.;;very=>“Very” không tạo cấu trúc kết quả với “that”, và không đứng trước mạo từ “a”.;;too=>“Too” cần tính từ và mang nghĩa quá mức, không kết hợp với “a long wait that...”.\nc|What the students most need ___ more practice in speaking.|are / be / it is / is|3|Mệnh đề What… + is + bổ ngữ; “more practice” là danh từ không đếm được, nên động từ là “is”.|are=>Mệnh đề What làm chủ ngữ coi là một khối số ít, và bổ ngữ “more practice” không đếm được.;;be=>Động từ chính của câu cần chia thì hiện tại, không để ở nguyên mẫu “be”.;;it is=>Không được thêm “it” sau mệnh đề What; câu sẽ có hai chủ ngữ.\nc|All I want to do ___ lie down and sleep for an hour.|is / are / does / being|0|Sau All I want to do thường dùng is + (to) + V; bỏ to cũng được vì trước đó đã có “do”.|are=>“All I want to do” là một khối số ít nên không chia “are”.;;does=>Động từ nối cần là “be”; “does” không nối chủ ngữ với “lie down”.;;being=>Dạng V-ing không thể làm động từ chính của câu ở đây.\nc|The new treatment is ___ means a cure, but it does reduce the pain.|in no / by no / at no / not in|1|By no means = hoàn toàn không; “but it does reduce the pain” cho thấy ý phủ định mạnh trước đó.|in no=>Cụm cố định là “by no means”, không dùng “in no means” trong nghĩa này.;;at no=>“At no” không tạo được cụm “at no means a cure” theo cách dùng thông thường.;;not in=>Sau “not in” cần “the least”; ở đây chỗ trống đứng trước “means”.\nc|I was not ___ the least interested in the offer, so I declined politely.|at / by / in / on|2|Cụm cố định là not in the least (hoàn toàn không); “declined politely” xác nhận ý không hứng thú.|at=>“Not at all” là cụm khác, còn “not at the least” không phải cách nói tự nhiên.;;by=>“By” kết hợp thành “by no means”, không dùng với “the least” trong cụm phủ định này.;;on=>“On the least” không tạo thành cụm phủ định nhấn mạnh trong tiếng Anh.\nc|Our budget is ___ small to cover a project of this size, I'm afraid.|too much / enough / so far / far too|3|Far too + tính từ nhấn mạnh mức độ quá đáng; “I'm afraid” cho thấy ngân sách không đủ.|too much=>“Too much” đi với danh từ không đếm được, còn ở đây cần bổ nghĩa tính từ “small”.;;enough=>“Enough” đứng sau tính từ và nghĩa ngược lại, không hợp với “to cover” theo nghĩa quá nhỏ.;;so far=>“So far” nghĩa là cho đến nay, không bổ nghĩa cho tính từ “small”.\nc|What ___ a difference a good night's sleep makes to concentration!|a / an / the / such|0|Câu cảm thán dùng What + a + (tính từ) + danh từ số ít đếm được; difference bắt đầu bằng phụ âm.|an=>“Difference” bắt đầu bằng phụ âm /d/ nên dùng “a”, không dùng “an”.;;the=>Cấu trúc cảm thán là What + a + danh từ, không dùng mạo từ xác định “the”.;;such=>“What such a” không tồn tại; What đã đảm nhiệm vai trò nhấn mạnh rồi.\nc|We were told the conference would be dull, but ___ it was extremely well organised.|what / in fact / in the least / by no means|1|Vế sau trái với tin đồn nên cần cụm khẳng định như in fact; hai cụm phủ định không hợp nghĩa.|what=>“What” ở đây không đủ nghĩa liên kết và không thể đứng trước “it was” như một trạng ngữ.;;in the least=>Cụm này chỉ dùng trong câu phủ định, trong khi vế sau mang nghĩa khẳng định.;;by no means=>Cụm này mang nghĩa phủ định mạnh, mâu thuẫn với “extremely well organised”.\nc|Nobody else could have fixed it; the engineer ___ admitted the design was faulty.|him / his / himself / he|2|Chính người kỹ sư thừa nhận, nên dùng himself đứng sau chủ ngữ để nhấn mạnh; engineer là nam.|him=>“Him” là tân ngữ, không dùng làm từ nhấn mạnh đứng sau danh từ chủ ngữ.;;his=>“His” là tính từ sở hữu, phải đi kèm danh từ nên không đứng trước “admitted”.;;he=>“He” lặp chủ ngữ và không mang nghĩa nhấn mạnh chính người kỹ sư đó.\nc|It was ___ beautiful a morning that we decided to walk to work.|such / very / how / so|3|Cấu trúc so + tính từ + a + danh từ + that là kiểu trang trọng; thứ tự “beautiful a morning” báo hiệu dùng so.|such=>“Such” đi với “a + tính từ + danh từ”, còn ở đây đã có tính từ ngay trước “a morning” theo thứ tự so + adj + a.;;very=>“Very” không đứng trước “a” theo thứ tự này và không tạo cấu trúc kết quả.;;how=>“How” dùng trong câu cảm thán, không kết hợp với “that we decided” như vậy.\nx|Chọn câu đúng (nhấn mạnh bằng did)|I did told the nurse about my allergy before the operation. / I did tell the nurse about my allergy before the operation. / I done tell the nurse about my allergy before the operation. / I did telling the nurse about my allergy before the operation.|1|Did nhấn mạnh + động từ nguyên mẫu; câu đúng khẳng định mình đã báo y tá.|I did told the nurse about my allergy before the operation.=>Sau “did” nhấn mạnh phải dùng nguyên mẫu, “told” bị chia quá khứ hai lần.;;I done tell the nurse about my allergy before the operation.=>“Done” không phải trợ động từ nhấn mạnh trong tiếng Anh chuẩn.;;I did telling the nurse about my allergy before the operation.=>Sau “did” không dùng V-ing, chỉ dùng động từ nguyên mẫu.\nx|Chọn câu đúng (mệnh đề What)|What I enjoy most about the job is working with young patients. / What I enjoy most about the job it is working with young patients. / What I enjoy most about the job are working with young patients. / That I enjoy most about the job is working with young patients.|0|What + mệnh đề + is + V-ing/N làm nổi bật phần cuối; không có “it” thừa.|What I enjoy most about the job it is working with young patients.=>Mệnh đề What đã là chủ ngữ nên không thêm “it” trước động từ be.;;What I enjoy most about the job are working with young patients.=>Mệnh đề What cùng bổ ngữ V-ing đi với động từ số ít “is”.;;That I enjoy most about the job is working with young patients.=>Dùng “That” thay cho “What” sẽ làm mất nghĩa “điều mà” của mệnh đề.\nx|Chọn câu đúng (đại từ phản thân)|The manager she carried the boxes upstairs. / The manager hers carried the boxes upstairs. / The manager herself carried the boxes upstairs. / The manager her own carried the boxes upstairs.|2|Danh từ + herself nhấn mạnh chính người đó làm việc, không ai khác.|The manager she carried the boxes upstairs.=>Đại từ chủ ngữ “she” lặp lại, không thể thay thế đại từ phản thân nhấn mạnh.;;The manager hers carried the boxes upstairs.=>“Hers” là đại từ sở hữu, không đứng sau danh từ để nhấn mạnh.;;The manager her own carried the boxes upstairs.=>“Her own” cần danh từ theo sau, không dùng làm từ nhấn mạnh chủ thể.\nx|Chọn câu đúng (phủ định nhấn mạnh)|She is by no mean ready for such a demanding role. / She is by no means ready for so a demanding role. / She is no by means ready for such a demanding role. / She is by no means ready for such a demanding role.|3|By no means đứng trước tính từ để phủ định mạnh; such a + adj + N đúng cấu trúc.|She is by no mean ready for such a demanding role.=>Cụm cố định là “by no means” với “means” số nhiều.;;She is by no means ready for so a demanding role.=>“So” không đứng trước “a demanding role”; cần such hoặc so + adj + a.;;She is no by means ready for such a demanding role.=>Trật tự từ trong cụm cố định bị đảo, đúng phải là “by no means”.\nt|I did ___ (call) you yesterday, but your phone was switched off.|call|Sau did nhấn mạnh dùng động từ nguyên mẫu, nên điền “call”.\nt|She ___ (do) look tired, so perhaps we should end the meeting.|does|Chủ ngữ she ở hiện tại nên dùng does nhấn mạnh trước nguyên mẫu “look”.\nt|The mayor ___ (he) opened the new health centre last week.|himself|Dạng phản thân nhấn mạnh của he là himself, đứng sau danh từ chủ ngữ.\nt|What I really need ___ (be) a long holiday.|is|Mệnh đề What làm chủ ngữ số ít ở hiện tại nên động từ là is.\nf|It was so a stressful week that I slept for twelve hours.|so|such|Trước “a stressful week” (a + tính từ + danh từ) phải dùng such, không dùng so.\nf|What an remarkable recovery she has made after the surgery!|an|a|Remarkable bắt đầu bằng phụ âm /r/ nên mạo từ sau What phải là a, không phải an.\nf|All she wanted were a quiet corner to read in.|were|was|Mệnh đề All she wanted coi là số ít và bổ ngữ là “a quiet corner”, nên dùng was.\no|What surprised everyone was how quickly she recovered.|Mệnh đề What làm chủ ngữ, theo sau là was và mệnh đề với how nêu thông tin chính.\no|The results were not in the least disappointing.|Cụm not in the least đứng trước tính từ để phủ định nhấn mạnh.","modals-advanced":"c|You were supposed to meet us at eight. You ___ outside the lecture hall, but you were still at home.|should have been waiting / should be waiting / must have been waiting / might be waiting|0|Phê bình việc lẽ ra đang diễn ra trong quá khứ dùng should have been + V-ing; mệnh đề “but you were still at home” cho thấy bạn đã không đợi.|should be waiting=>Should be waiting nói về hiện tại, trong khi câu nói về lúc tám giờ trong quá khứ nên không khớp thời gian.;;must have been waiting=>Must have been waiting là suy luận rằng bạn đã đợi, mâu thuẫn với vế sau nói bạn vẫn ở nhà.;;might be waiting=>Might be waiting chỉ khả năng ở hiện tại, không diễn đạt được ý trách móc về việc lẽ ra phải làm.\nc|It's ten at night and the lab light is still on, so Dr Hale ___ on his report.|must have worked / ought to work / must be working / can't have been working|2|Suy luận chắc chắn về hành động đang diễn ra ngay bây giờ dùng must be + V-ing; “still on” cho thấy việc đang tiếp diễn.|must have worked=>Must have worked nói về hành động đã hoàn tất trong quá khứ, trong khi đèn vẫn đang sáng ở hiện tại.;;ought to work=>Ought to work là lời khuyên, không phải suy luận từ bằng chứng là đèn còn sáng.;;can't have been working=>Can't have been working phủ định việc đã xảy ra trong quá khứ, trái với bằng chứng đèn vẫn sáng.\nc|We took a taxi, but the meeting started late. We ___ hurried.|needn't / needn't have / didn't need / mustn't have|1|Needn't have + V3 nói hành động đã xảy ra nhưng không cần thiết; “took a taxi” và “started late” cho thấy sự vội vã là thừa.|needn't=>Needn't hurried sai cấu trúc vì sau needn't phải là động từ nguyên mẫu, ở đây lại là quá khứ phân từ.;;didn't need=>Didn't need hurried sai ngữ pháp vì didn't need cần đi với to V hoặc động từ nguyên mẫu, không phải dạng quá khứ.;;mustn't have=>Mustn't have hurried là suy luận về điều không thể, nghĩa không hợp với việc đã vội vì cuộc họp bắt đầu muộn.\nc|According to the notice, the new regulations ___ come into force on 1 January.|are going / are able to / are about / are to|3|Be to + V diễn đạt sắp xếp hoặc kế hoạch chính thức; trước “come into force” cần are to, và “according to the notice” cho thấy văn phong trang trọng.|are going=>Are going cần to để thành are going to come, nên ở đây thiếu to và câu không thành cấu trúc đúng.;;are able to=>Are able to nghĩa là có khả năng, không phải một sự sắp xếp, và không hợp với quy định có hiệu lực.;;are about=>Are about cần to để thành are about to come, vì vậy thiếu to nên sai cấu trúc trong câu này.\nc|My aunt is very patient: she ___ sit for hours beside a patient who cannot sleep.|would / is to / shall / will|3|Will + V diễn tả hành vi điển hình ở hiện tại; “is very patient” là thì hiện tại nên dùng will chứ không dùng would.|would=>Would sit chỉ thói quen trong quá khứ, trong khi câu dùng “is” cho thấy đang nói hiện tại.;;is to=>Is to sit là mệnh lệnh hoặc sắp xếp, không diễn tả thói quen điển hình của một người kiên nhẫn.;;shall=>Shall với ngôi thứ ba dùng cho quy định trang trọng, không diễn tả thói quen của một người.\nc|When I was a child, we ___ spend every summer at my grandmother's farm.|would / will / should / might as well|0|Would + V diễn tả thói quen lặp lại trong quá khứ; “when I was a child” và “every summer” là dấu hiệu rõ.|will=>Will spend chỉ thói quen ở hiện tại, không khớp với mệnh đề “when I was a child” ở quá khứ.;;should=>Should spend là lời khuyên hoặc bổn phận, không kể lại thói quen xảy ra mỗi mùa hè.;;might as well=>Might as well spend nghĩa là chẳng có lý do gì để không làm, không hợp với việc kể lại thói quen thời thơ ấu.\nc|The nurse looked at the heavy bag and asked, “___ I carry that up the stairs for you?”|Must / Will / Do / Shall|3|Shall dùng ở ngôi thứ nhất để đưa ra lời đề nghị giúp đỡ; câu “carry that up the stairs for you” cho thấy đây là một lời đề nghị.|Must=>Must I carry diễn tả nghĩa vụ bực bội, không phải lời đề nghị lịch sự giúp người khác.;;Will=>Will I carry hỏi về tương lai chứ không phải đề nghị, nên nghe không tự nhiên trong tình huống này.;;Do=>Do I carry không đi với động từ nguyên mẫu theo cách này để đề nghị, và nghĩa thành câu hỏi thông tin.\nx|Chọn câu đúng (needn't have)|You needn't to have come; I had finished everything. / You needn't have come; I had finished everything. / You needn't have came; I had finished everything. / You didn't need have come; I had finished everything.|1|Sau needn't dùng have + quá khứ phân từ, không có to; vế sau cho thấy việc đến là không cần thiết dù đã xảy ra.|You needn't to have come; I had finished everything.=>Needn't to là lỗi vì needn't là khuyết thiếu và phải đi với động từ nguyên mẫu không to.;;You needn't have came; I had finished everything.=>Needn't have came sai vì sau have phải là quá khứ phân từ come, không phải dạng quá khứ đơn came.;;You didn't need have come; I had finished everything.=>Didn't need have come sai cấu trúc vì didn't need đi với to V, không đi với have + V3 theo cách này.\nx|Chọn câu đúng (might as well)|Since the shop is closed, we might as well to go home. / Since the shop is closed, we might as well going home. / Since the shop is closed, we might well as go home. / Since the shop is closed, we might as well go home.|3|Might as well + động từ nguyên mẫu không to nghĩa là “chẳng có lý do gì để không”; vế “the shop is closed” đưa ra lý do.|Since the shop is closed, we might as well to go home.=>Might as well to go sai vì sau might as well không dùng to trước động từ nguyên mẫu.;;Since the shop is closed, we might as well going home.=>Might as well going sai vì sau cụm này phải là động từ nguyên mẫu, không phải V-ing.;;Since the shop is closed, we might well as go home.=>Might well as go sai trật tự cụm cố định; đúng phải là might as well, còn might well mang nghĩa khác.\nt|I wouldn't dare ___ (ask) the director for another week off.|ask|Dare dùng như khuyết thiếu hoặc với wouldn't dare thì theo sau là động từ nguyên mẫu không to.\nt|The lights are on in the lab, so someone must ___ (work) there right now.|be working|Suy luận về hành động đang diễn ra ở hiện tại dùng must be + V-ing, nhờ dấu hiệu right now.\nf|She needn't have went to the pharmacy because the nurse had already called.|went|gone|Sau needn't have phải là quá khứ phân từ gone, không phải dạng quá khứ đơn went.\nc|Yesterday was a public holiday, so the staff ___; most of them stayed at home.|needn't have come / didn't need to come / needn't come / mustn't come|1|Didn't need to nói việc không cần thiết mà không cho biết có làm hay không; vế “most of them stayed at home” cho thấy họ đã không đến.|needn't have come=>Needn't have come ngụ ý họ đã đến mà không cần, mâu thuẫn với vế sau nói hầu hết ở nhà.;;needn't come=>Needn't come mang nghĩa hiện tại hoặc tương lai, không phù hợp với “yesterday” ở quá khứ.;;mustn't come=>Mustn't come là lệnh cấm, không đúng nghĩa vì ngày lễ chỉ khiến việc đi làm là không cần thiết.\nc|Nurse Tran was furious. “How ___ you speak to a patient like that?” she said.|do / would / dare / need|2|How dare you là cụm cố định thể hiện sự phẫn nộ, dare là khuyết thiếu nên theo sau là ngôi you rồi động từ nguyên mẫu.|do=>How do you speak là câu hỏi cách thức bình thường, không mang sắc thái giận dữ và trách móc như ngữ cảnh.;;would=>How would you speak hỏi về cách nói giả định, không phải lời quở trách đang diễn ra.;;need=>How need you speak không tạo thành cụm tự nhiên; need không đi với how theo nghĩa phẫn nộ này.\nc|You ___ apologise; nobody was offended by the remark.|don't need / needn't to / mustn't / needn't|3|Needn't là khuyết thiếu nên đi thẳng với động từ nguyên mẫu không to, và nghĩa “không cần” hợp với “nobody was offended”.|don't need=>Don't need apologise thiếu to, vì don't need là động từ thường nên phải là don't need to apologise.;;needn't to=>Needn't to sai vì needn't là khuyết thiếu và không đi kèm to trước động từ.;;mustn't=>Mustn't apologise nghĩa là cấm xin lỗi, không hợp với ý chỉ là việc đó không cần thiết.\nc|The trial results ___ change how doctors treat the illness; experts are cautious but hopeful.|may well / may as well / might as well / would rather|0|May well + V nghĩa là rất có khả năng; “cautious but hopeful” thể hiện khả năng cao chứ không phải đề xuất hành động.|may as well=>May as well + V nghĩa là chẳng có lý do gì để không làm, không nói về khả năng thay đổi.;;might as well=>Might as well + V cũng là cụm đề xuất hợp lý, không diễn đạt xác suất thay đổi của kết quả.;;would rather=>Would rather + V diễn đạt sở thích, không phù hợp để dự đoán tác động của kết quả thử nghiệm.\nc|I'd rather ___ at home tonight than queue for tickets in the rain.|stayed / stay / to stay / staying|1|Would rather được theo sau bởi động từ nguyên mẫu không to khi nói sở thích về hiện tại hoặc tương lai; “tonight” cho thấy đây là tương lai.|stayed=>Stayed sau would rather dùng khi chủ ngữ khác nhau hoặc nói về quá khứ, không phải sở thích của chính người nói tối nay.;;to stay=>To stay sai vì would rather đi với động từ nguyên mẫu không to.;;staying=>Staying không dùng sau would rather; cấu trúc này cần động từ nguyên mẫu không to.\nc|At that hour the technician ___ the equipment, but he was on a break instead.|ought to check / must have been checking / ought to have been checking / may be checking|2|Ought to have been + V-ing phê bình việc lẽ ra đang diễn ra trong quá khứ; “but he was on a break instead” cho thấy anh ấy đã không làm.|ought to check=>Ought to check nói về bổn phận ở hiện tại hoặc tương lai, không nói về một thời điểm đã qua.;;must have been checking=>Must have been checking khẳng định anh ấy đã kiểm tra, mâu thuẫn với việc anh ấy nghỉ giải lao.;;may be checking=>May be checking suy đoán ở hiện tại, không diễn tả việc lẽ ra phải làm trong quá khứ.\nc|If anyone ___ ask, tell them I've gone to the clinic and will be back by noon.|would / might / will / should|3|Should trong mệnh đề if diễn tả giả định ít khả năng xảy ra, thường dùng trong văn phong lịch sự; “if anyone ___ ask” phù hợp với cách dùng này.|would=>Would trong mệnh đề if không đúng vì would không dùng để diễn tả giả định về một sự việc có thể xảy ra như vậy.;;might=>Might sau if anyone không tự nhiên và không dùng để nêu giả định như cấu trúc if + should.;;will=>Will ở mệnh đề if chỉ dùng cho lời nhờ vả hoặc sẵn lòng, không phải giả định về việc có người hỏi.\nx|Chọn câu đúng (be to)|The ambassador is to arrive at noon, and the guards are to stand at the gate. / The ambassador is to arrives at noon, and the guards are to stand at the gate. / The ambassador is to be arrive at noon, and the guards are to stand at the gate. / The ambassador to arrive at noon is, and the guards are to stand at the gate.|0|Be to + động từ nguyên mẫu diễn tả kế hoạch hoặc mệnh lệnh chính thức, mỗi chủ ngữ phải có dạng be phù hợp.|The ambassador is to arrives at noon, and the guards are to stand at the gate.=>Is to arrives sai vì sau to phải là động từ nguyên mẫu không chia, không thêm -s.;;The ambassador is to be arrive at noon, and the guards are to stand at the gate.=>Is to be arrive sai vì là hai động từ nguyên mẫu liên tiếp, không đúng cấu trúc be to + V.;;The ambassador to arrive at noon is, and the guards are to stand at the gate.=>To arrive at noon is đảo trật tự làm câu mất cấu trúc be to + V và không thành câu hoàn chỉnh.\nt|As a student, she would ___ (spend) every evening in the library.|spend|Would chỉ thói quen quá khứ nên theo sau là động từ nguyên mẫu không to.\nt|Last night you ought to ___ (wait) in the car, not walking around the car park.|have been waiting|Phê bình việc lẽ ra đang diễn ra trong quá khứ dùng ought to have been + V-ing.\nf|My brother must be study in the library now because he left an hour ago.|study|studying|Suy luận về hành động đang diễn ra dùng must be + V-ing, nên study phải đổi thành studying.\no|Staff are not to use the lift during a fire alarm.|Be to + V dùng cho lệnh chính thức; phủ định đặt not sau are rồi đến to + động từ.","passive-advanced":"c|The final report ___ to the board before the end of the month.|must be submitted / must submit / must be submit / must been submitted|0|Động từ khuyết thiếu + be + V3 tạo bị động; chủ ngữ “report” là vật chịu tác động nên cần dạng bị động.|must submit=>Chủ ngữ “report” là vật không thể tự nộp nên cần bị động; câu này thiếu “be” và dạng V3.;;must be submit=>Sau “be” trong câu bị động phải dùng quá khứ phân từ “submitted”, không dùng nguyên mẫu.;;must been submitted=>Sau động từ khuyết thiếu phải dùng “be”, không dùng “been” vì “been” chỉ đi với “have”.\nc|The patients ought to ___ about the risks before the operation.|be warned / have been warned / have warned / having been warned|1|“Ought to have been + V3” diễn tả việc lẽ ra phải được làm trong quá khứ; “before the operation” là dấu hiệu quá khứ.|be warned=>“Be warned” chỉ việc cần làm từ bây giờ, trong khi “before the operation” nói về việc đã lẽ ra xảy ra.;;have warned=>Dạng chủ động nghĩa là bệnh nhân đã đi cảnh báo người khác, trái với nghĩa của câu.;;having been warned=>Sau “ought to” phải dùng nguyên mẫu không “to” đã chia, không dùng dạng danh động từ “having been”.\nc|She hates ___ to repeat the same instructions every morning.|asking / to ask / being asked / been asked|2|Sau “hate” dùng danh động từ bị động “being + V3” khi chủ ngữ nhận hành động; ở đây cô ấy bị yêu cầu lặp lại hướng dẫn.|asking=>Dạng chủ động nghĩa là cô ấy là người đi hỏi người khác, trái với ý cô bị yêu cầu.;;to ask=>Nguyên mẫu chủ động cũng có nghĩa cô ấy đi hỏi, không phải bị yêu cầu lặp lại.;;been asked=>Sau “hates” cần danh động từ “being”, không dùng quá khứ phân từ “been asked” đứng một mình.\nc|The meeting has been ___ until the director returns from Hanoi.|put away / put out / put up / put off|3|“Put off” nghĩa là hoãn lại; dấu hiệu là “until the director returns” cho thấy cuộc họp bị dời lại.|put away=>“Put away” nghĩa là cất đi, không có nghĩa hoãn một cuộc họp.;;put out=>“Put out” nghĩa là dập tắt hoặc đưa ra, không hợp với việc hoãn họp đến khi giám đốc về.;;put up=>“Put up” nghĩa là dựng lên hoặc cho ở nhờ, không mang nghĩa hoãn lại.\nc|A scholarship ___ to her by the university last spring.|was awarded / awarded / was awarding / has been awarded|0|Với mốc quá khứ xác định “last spring” dùng quá khứ đơn bị động “was awarded”; tân ngữ trực tiếp là chủ ngữ nên có “to her”.|awarded=>Thiếu trợ động từ “was”; chỉ V3 không thể làm động từ chính của câu bị động.;;was awarding=>“Was awarding” là chủ động tiếp diễn, trái với nghĩa vì học bổng không tự trao cho ai.;;has been awarded=>Hiện tại hoàn thành không hợp với “last spring”, một mốc thời gian quá khứ xác định.\nc|They were all ___ a copy of the safety guidelines on arrival.|gave / given / giving / give|1|Với động từ hai tân ngữ, chuyển người nhận làm chủ ngữ rồi dùng was/were + V3; “They were given a copy”.|gave=>Câu bị động cần quá khứ phân từ “given”, không dùng quá khứ đơn “gave” sau “were”.;;giving=>“Were giving” là chủ động tiếp diễn, nhưng chủ ngữ “they” là người nhận hướng dẫn.;;give=>Sau “were” trong bị động phải dùng V3, không dùng nguyên mẫu “give”.\nx|Chọn câu đúng|The old hospital wing is being refurbished at the moment. / The old hospital wing is refurbished at the moment now. / The old hospital wing is being refurbish at the moment. / The old hospital wing is refurbishing at the moment.|0|Bị động tiếp diễn có dạng is/are being + V3; dấu hiệu “at the moment” cho thấy hành động đang diễn ra.|The old hospital wing is refurbished at the moment now.=>Hiện tại đơn bị động không diễn tả được việc đang diễn ra; còn thêm “now” thừa trong câu.;;The old hospital wing is being refurbish at the moment.=>Sau “being” phải dùng quá khứ phân từ “refurbished”, không dùng nguyên mẫu.;;The old hospital wing is refurbishing at the moment.=>Cánh nhà không thể tự tu sửa chính nó nên dạng chủ động này sai nghĩa.\nx|Chọn câu đúng|The decision was happened without any consultation. / The decision was made without any consultation. / The decision made without any consultation. / The decision was making without any consultation.|1|“Make a decision” là ngoại động từ nên có bị động “was made”; không dùng bị động với nội động từ như “happen”.|The decision was happened without any consultation.=>“Happen” là nội động từ nên không thể chuyển sang bị động, nên không thể nói “was happened”.;;The decision made without any consultation.=>Thiếu trợ động từ “was” nên câu thiếu động từ chính hoàn chỉnh.;;The decision was making without any consultation.=>“Was making” là chủ động tiếp diễn, sai nghĩa với quyết định bị đưa ra.\nt|I need my blood pressure ___ (check) by a nurse every week.|checked|Sau “need my blood pressure” cần quá khứ phân từ với nghĩa bị động: “checked”.\nt|The suspect is believed ___ (leave) the country two days ago.|to have left|Hành động xảy ra trước hiện tại nên dùng nguyên mẫu hoàn thành “to have left” sau “is believed”.\nf|Several issues still need to be dealt it with before the merger.|it|(delete)|Trong bị động, “dealt with” không cần tân ngữ “it” vì chủ ngữ “issues” đã là tân ngữ của “deal with”.\no|The new policy will be introduced by the government next year.|Chủ ngữ + will be + V3 + by-agent + trạng từ thời gian ở cuối câu.\nc|The lab technician resents ___ the blame although the delay was not her fault.|giving / to be given / being given / been given|2|Sau “resent” dùng danh động từ; cô ấy nhận sự đổ lỗi nên cần bị động “being given”, và mệnh đề “not her fault” cho thấy ý đó.|giving=>Dạng chủ động nghĩa là cô ấy đi đổ lỗi cho người khác, trái với ý cô bị đổ lỗi dù không có lỗi.;;to be given=>Sau “resent” dùng danh động từ chứ không dùng nguyên mẫu có “to”, nên câu này sai cấu trúc.;;been given=>“Been given” thiếu “being”; sau “resents” cần danh động từ “being + V3”.\nc|Applications must ___ by noon on Friday, or they will not be considered.|receive / be receiving / have received / be received|3|Sau động từ khuyết thiếu “must” dùng be + V3 khi chủ ngữ là vật được nhận; “applications” và “will not be considered” xác nhận nghĩa bị động.|receive=>Chủ ngữ “applications” là hồ sơ nên không tự nhận được gì; thiếu “be” và dạng V3 của bị động.;;be receiving=>“Be receiving” là dạng chủ động tiếp diễn, không hợp với hồ sơ là vật được nhận.;;have received=>Dạng chủ động hoàn thành nghĩa là hồ sơ đi nhận cái gì đó, trái với nghĩa của câu.\nc|The elderly patients are well ___ by the night staff.|looked after / looked for / looked into / looked up|0|“Look after” nghĩa là chăm sóc và giữ nguyên giới từ khi chuyển sang bị động; “patients” và “night staff” gợi nghĩa chăm sóc.|looked for=>“Look for” nghĩa là tìm kiếm, không hợp với việc nhân viên chăm sóc bệnh nhân.;;looked into=>“Look into” nghĩa là điều tra, không dùng để nói về việc chăm sóc người.;;looked up=>“Look up” nghĩa là tra cứu hoặc khá lên, không mang nghĩa chăm sóc.\nc|The new vaccine is expected ___ available next autumn.|being / to be / to have been / be|1|Cấu trúc “is expected to be” nói về việc tương lai; “next autumn” là dấu hiệu tương lai nên không dùng dạng hoàn thành.|being=>Sau “is expected” cần nguyên mẫu có “to”, không dùng danh động từ “being”.;;to have been=>Nguyên mẫu hoàn thành chỉ việc đã xảy ra, nhưng “next autumn” là tương lai nên sai.;;be=>Sau “expected” phải có “to”; nguyên mẫu trần “be” không dùng được ở đây.\nc|He had his driving licence ___ after the accident.|suspending / suspend / suspended / to suspend|2|Cấu trúc have + vật + V3 nói về việc xảy ra với vật của mình; giấy phép bị đình chỉ nên cần “suspended”, và “after the accident” giải thích lý do.|suspending=>Với “have + tân ngữ” nghĩa nhờ hoặc bị làm gì, cần V3 chứ không dùng V-ing trong câu này.;;suspend=>Nguyên mẫu trần sẽ nghĩa là anh ta bắt ai đó đình chỉ giấy phép, không phải bị đình chỉ.;;to suspend=>Dạng “to suspend” là chủ động, trái với việc giấy phép bị cơ quan chức năng đình chỉ.\nc|Visitors are kindly requested ___ their mobile phones switched off.|keeping / to be keeping / keep / to keep|3|“Be requested to V” là cấu trúc trang trọng để đưa ra yêu cầu; “kindly” và “visitors” là dấu hiệu văn phong thông báo chính thức.|keeping=>Sau “requested” cần nguyên mẫu có “to”, không dùng danh động từ trong cấu trúc bị động này.;;to be keeping=>Dạng tiếp diễn này không phù hợp với lời đề nghị trang trọng, và nghĩa của câu bị lệch đi.;;keep=>Sau “are requested” phải có “to”; nguyên mẫu trần “keep” sai cấu trúc.\nx|Chọn câu đúng|She showed the results by the consultant. / The results were shown her to the consultant. / She was shown the results by the consultant. / She was shown to the results by the consultant.|2|Với động từ hai tân ngữ “show”, người nhận có thể làm chủ ngữ: “She was shown the results”.|She showed the results by the consultant.=>Dạng chủ động “showed” không đi với “by the consultant”; câu cần bị động để người tư vấn là tác nhân.;;The results were shown her to the consultant.=>Cụm “to the consultant” làm sai nghĩa vì người tư vấn là người cho xem, không phải người nhận.;;She was shown to the results by the consultant.=>Thêm “to” trước “the results” làm câu sai nghĩa, vì tân ngữ trực tiếp không cần giới từ.\nx|Chọn câu đúng|Several patients have sent home early. / Several patients have been sending home early. / Several patients were been sent home early. / Several patients have been sent home early.|3|Hiện tại hoàn thành bị động có dạng have been + V3; bệnh nhân được cho về nên dùng “been sent”.|Several patients have sent home early.=>Thiếu “been” nên không thành bị động; bệnh nhân không tự gửi người khác về nhà.;;Several patients have been sending home early.=>“Been sending” là dạng chủ động tiếp diễn, không hợp với bệnh nhân là người được cho về.;;Several patients were been sent home early.=>Không dùng “were been”; “been” chỉ đi sau “have/has/had”, nên câu sai cấu trúc.\nt|The new wing is currently ___ (build), so access is limited.|being built|Hiện tại tiếp diễn bị động dùng is being + V3; “currently” cho thấy việc đang diễn ra.\nt|Nobody likes ___ (tell) what to do in front of colleagues.|being told|Sau “like” dùng danh động từ bị động “being told” vì mọi người là người bị bảo.\nf|The children are being looking after by their grandmother this week.|looking|looked|Bị động tiếp diễn có dạng being + V3, nên “looking” phải thành “looked”.\no|It is widely expected that interest rates will be reduced next spring.|Cấu trúc It is + V3 + that + mệnh đề, với bị động “will be reduced” và trạng từ thời gian ở cuối.","prepositional-phrases":"c|After the accident, the driver spent a week ___ hospital before he could go home.|in / at / on / to|0|Nằm viện với tư cách bệnh nhân dùng “in hospital” không mạo từ; “spent a week” cho thấy trạng thái ở lại điều trị.|at=>“At hospital” không dùng khi nói về bệnh nhân nằm viện; bệnh nhân phải dùng “in hospital” không mạo từ.;;on=>“On hospital” không tồn tại, giới từ này không đi với nơi điều trị bệnh nhân nằm lại.;;to=>“To” chỉ hướng đi tới, không diễn tả trạng thái đang nằm viện suốt một tuần.\nc|The factory was closed ___ the failure of the safety inspection.|in spite of / as a result of / instead of / apart from|1|Cần giới từ phức chỉ nguyên nhân – kết quả; “the failure of the safety inspection” là nguyên nhân nên dùng “as a result of”.|in spite of=>“In spite of” chỉ sự nhượng bộ; việc nhà máy đóng cửa là hậu quả, không phải điều trái với kỳ vọng.;;instead of=>“Instead of” nghĩa là thay vì, không diễn đạt quan hệ nguyên nhân với việc kiểm tra an toàn thất bại.;;apart from=>“Apart from” nghĩa là ngoài ra hoặc trừ ra, không chỉ nguyên nhân dẫn tới việc đóng cửa.\nc|There has been a steady rise ___ the number of students studying abroad.|of / on / in / at|2|“A rise in + danh từ” nêu thứ đang tăng; “the number of students” là đối tượng thay đổi trong câu này.|of=>Sau “a rise” để nói cái gì tăng phải dùng “in”; “of” chỉ dùng cho mức tăng như “a rise of 5%”.;;on=>“A rise on” không phải kết hợp đúng; danh từ rise đi với “in” khi nêu đối tượng thay đổi.;;at=>“At” không đi sau danh từ rise; nó thường chỉ điểm hoặc mức, không chỉ đối tượng tăng.\nc|Our train was delayed, but we reached the airport ___ time to check in.|on / at / by / in|3|“In time to + V” nghĩa là kịp làm gì; “delayed” và “to check in” cho thấy ý kịp lúc chứ không phải đúng lịch.|on=>“On time” nghĩa là đúng giờ theo lịch; còn “time to check in” cần “in time” (kịp để làm gì).;;at=>“At time” không là cụm cố định; “at times” mới có nghĩa thỉnh thoảng nhưng không hợp câu.;;by=>“By time” không tồn tại; cụm đúng nghĩa là kịp để làm gì là “in time to + V”.\nc|The trains run every ten minutes, and all of them leave ___ time.|on / in / at / for|0|“On time” nghĩa là đúng giờ theo lịch; “run every ten minutes” cho thấy lịch trình, không phải kịp làm việc gì.|in=>“In time” nghĩa là kịp lúc cho một việc khác, không diễn đạt tàu rời ga đúng lịch trình.;;at=>“At time” không phải cụm cố định, nên không dùng để nói tàu chạy đúng giờ.;;for=>“For time” không tạo thành cụm có nghĩa đúng giờ trong tiếng Anh.\nc|We discussed many proposals, and ___ we chose the cheapest one.|at the end / in the end / by the end / in the ending|1|“In the end” nghĩa là rốt cuộc, sau một quá trình; “we discussed many proposals” cho thấy kết quả cuối cùng.|at the end=>“At the end” cần có “of” + danh từ, ví dụ “at the end of the meeting”; không đứng một mình.;;by the end=>“By the end” cũng cần “of + danh từ” và chỉ mốc thời hạn, không diễn tả kết quả cuối cùng.;;in the ending=>“In the ending” không phải cách nói tự nhiên; cụm cố định chỉ kết cục sau cân nhắc là “in the end”.\nc|The report must be submitted ___ Friday at the latest; after that it will not be accepted.|until / to / by / at|2|“By” chỉ hạn chót, nghĩa là không muộn hơn; “at the latest” và hành động nộp một lần xác nhận cách dùng này.|until=>“Until” chỉ việc kéo dài liên tục đến một mốc, còn nộp báo cáo là hành động một lần, cần “by”.;;to=>“To” không dùng để chỉ hạn chót nộp bài trong câu này, nên không tạo cụm đúng.;;at=>“At” đi với giờ cụ thể như at noon, không đi với ngày Friday trong nghĩa hạn chót.\nc|The office will be closed ___ Monday, so please call again then.|by / to / at / until|3|“Until” dùng cho trạng thái kéo dài đến một mốc; “closed” là trạng thái liên tục tới thứ Hai nên chọn “until”.|by=>“By” chỉ hạn chót của một hành động, còn văn phòng đóng cửa là trạng thái kéo dài đến thứ Hai.;;to=>“To Monday” thiếu tự nhiên; khi nói trạng thái kéo dài liên tục, dùng “until”.;;at=>“At Monday” sai vì “at” không đi với tên ngày trong tuần.\nc|The new manager is now ___ charge of the entire marketing department.|on / in / at / under|1|“In charge of + danh từ” nghĩa là phụ trách; “manager” và “entire department” cho thấy trách nhiệm quản lý.|on=>“On charge” không phải cụm cố định; với nghĩa phụ trách, cụm đúng là “in charge of”.;;at=>“At charge” không có nghĩa phụ trách; nó giống với nghĩa giá cước hơn là vai trò quản lý.;;under=>“Under charge” không dùng; còn “under the charge of” mới có nghĩa dưới quyền ai, khác cấu trúc ở đây.\nc|Elderly people living alone are particularly ___ risk during the cold weather.|at / in / under / on|0|“At risk” là cụm cố định nghĩa là có nguy cơ; “particularly” và “during the cold weather” mô tả nhóm dễ bị ảnh hưởng.|in=>“In risk” sai vì cụm cố định là “at risk”; “in danger” mới dùng “in”.;;under=>“Under risk” không tồn tại trong tiếng Anh chuẩn, dù “under pressure” là cụm đúng khác.;;on=>“On risk” không là cụm cố định; nghĩa bị đe dọa chỉ có trong “at risk”.\nc|The company will pay compensation ___ the event of a delay of more than two hours.|at / on / by / in|3|“In the event of + danh từ” nghĩa là trong trường hợp xảy ra; “compensation” và “delay” cho thấy tình huống điều kiện.|at=>“At the event” có thể nghĩa là tại sự kiện, nhưng ở đây cần “in the event of” mang nghĩa nếu xảy ra.;;on=>“On the event of” không phải cụm cố định để nói nếu xảy ra; cụm đúng dùng giới từ “in”.;;by=>“By the event of” sai vì không có nghĩa nếu xảy ra; “by” không tạo thành cụm giới từ này.\nc|The new treatment was assessed ___ its cost and its effect on patients' quality of life.|in spite of / instead of / in terms of / on account of|2|“In terms of” giới thiệu khía cạnh dùng để đánh giá; “assessed” và hai tiêu chí phía sau xác nhận nghĩa này.|in spite of=>“In spite of” nghĩa là bất chấp, không hợp khi chỉ tiêu chí đánh giá cost và quality of life.;;instead of=>“Instead of” nghĩa là thay vì; câu này liệt kê tiêu chí đánh giá chứ không thay thế một thứ khác.;;on account of=>“On account of” chỉ lý do; còn câu đang nêu khía cạnh dùng để đánh giá, nên cần “in terms of”.\nc|The school was closed for two days ___ the heavy snowfall.|in spite of / owing to / instead of / apart from|1|“Owing to + danh từ” chỉ nguyên nhân; “closed” và “heavy snowfall” cho thấy tuyết là lý do trường đóng cửa.|in spite of=>“In spite of” chỉ sự bất chấp; trường đóng cửa vì tuyết, không phải bất chấp tuyết rơi.;;instead of=>“Instead of” nghĩa là thay vì và đứng trước lựa chọn bị thay thế, không chỉ nguyên nhân đóng cửa.;;apart from=>“Apart from” nghĩa là ngoài ra; nó không nối được việc đóng cửa với nguyên nhân là tuyết dày.\nc|Many young workers are ___ stress when their workload suddenly increases.|subject to / aware of / capable of / prone to|3|“Prone to + danh từ” nghĩa là dễ bị; “stress when workload increases” mô tả xu hướng chứ không phải khả năng.|subject to=>“Subject to” nghĩa là phụ thuộc hoặc chịu sự điều chỉnh, không diễn tả xu hướng dễ bị căng thẳng.;;aware of=>“Aware of” nghĩa là nhận thức được; câu muốn nói họ dễ bị căng thẳng chứ không chỉ nhận biết nó.;;capable of=>“Capable of” nghĩa là có khả năng làm gì, không hợp với việc dễ bị căng thẳng.\nx|Chọn câu đúng|All visitors are asked to leave the building on foot in the event of fire. / The staff were angry in spite of the changes were announced late. / He is the person in charge for the project. / Due to the tests, he was prone of headaches.|0|Câu đúng dùng “on foot” (không mạo từ) và “in the event of fire” (danh từ không mạo từ); các câu còn lại sai giới từ hoặc cấu trúc.|The staff were angry in spite of the changes were announced late.=>“In spite of” phải đi với danh từ hoặc V-ing, không đi với một mệnh đề đầy đủ như “the changes were announced”.;;He is the person in charge for the project.=>Cụm cố định là “in charge of”, nên “for” sau “in charge” làm câu sai.;;Due to the tests, he was prone of headaches.=>Tính từ “prone” đi với “to”, không đi với “of”, nên cụm “prone of” sai.\nx|Chọn câu đúng|Despite of the delay, the surgery went ahead as planned. / Despite the delay, the surgery went ahead as planned. / Despite to the delay, the surgery went ahead as planned. / In despite the delay, the surgery went ahead as planned.|1|“Despite” đi thẳng với danh từ, không có “of” hay “to”; “in spite of” mới có “of”, nên chỉ câu thứ hai đúng.|Despite of the delay, the surgery went ahead as planned.=>“Despite” không đi với “of”; người Việt hay nhầm vì ghép với “in spite of”.;;Despite to the delay, the surgery went ahead as planned.=>“To” thừa sau “despite”; giới từ này tự nó đã đủ để nối với danh từ.;;In despite the delay, the surgery went ahead as planned.=>“In despite” không tồn tại; cụm có “in” phải là “in spite of”.\nx|Chọn câu đúng|The meeting finished at the end, and we all went home. / The meeting finished by the end, and we all went home. / In the end of the meeting, we all went home. / At the end of the meeting, we all went home.|3|“At the end of + danh từ” chỉ thời điểm kết thúc của một sự kiện; “in the end” không có “of” và mang nghĩa rốt cuộc.|The meeting finished at the end, and we all went home.=>“At the end” thiếu “of + danh từ” nên chưa nói rõ kết thúc của cái gì và nghe không tự nhiên.;;The meeting finished by the end, and we all went home.=>“By the end” cũng thiếu “of” và chỉ mốc thời hạn, không hợp với việc cuộc họp kết thúc.;;In the end of the meeting, we all went home.=>“In the end” không đi với “of”; khi có “of the meeting” phải dùng “at the end of”.\nx|Chọn câu đúng|There was a solution of the staffing problem last year. / We urgently need a solution to the staffing problem. / We urgently need a solution for to the staffing problem. / The solution at the staffing problem is simple.|1|Danh từ “solution” đi với “to” để nêu vấn đề được giải quyết, nên chỉ câu thứ hai đúng cấu trúc.|There was a solution of the staffing problem last year.=>“Solution of” không dùng để nêu vấn đề cần giải quyết; cụm chuẩn là “a solution to”.;;We urgently need a solution for to the staffing problem.=>Hai giới từ “for to” liên tiếp là thừa; chỉ cần một giới từ “to”.;;The solution at the staffing problem is simple.=>“At” không đi sau “solution”; giới từ đúng nối với vấn đề là “to”.\nt|The hospital is reviewing its procedures in ___ of the recent complaints. (one word)|view|“In view of + danh từ” nghĩa là xét đến; “recent complaints” là lý do khiến bệnh viện xem xét lại quy trình.\nt|On ___ of the whole department, I would like to thank our visitors. (one word)|behalf|“On behalf of” là cụm cố định nghĩa là thay mặt; “the whole department” là bên được thay mặt.\nt|We took the bus ___ (instead) of walking in the rain. (one word)|instead|“Instead of + V-ing” nghĩa là thay vì; sau “of” là “walking” ở dạng V-ing.\nt|___ from Lan, everyone in the group has finished the report. (one word)|apart|“Apart from + danh từ” nghĩa là trừ ra; Lan là ngoại lệ so với “everyone”.\nf|The lecture was cancelled due of the lecturer's illness.|of|to|Giới từ phức đúng là “due to”, nên “of” phải đổi thành “to”.\nf|There has been a significant increase on the price of fuel.|on|in|Sau “an increase” nêu đối tượng thay đổi bằng “in”, nên “on” sai.\nf|Her proposal is subject for approval by the board.|for|to|Tính từ “subject” đi với “to” khi nghĩa là phụ thuộc, nên “for” phải đổi thành “to”.\no|In spite of the heavy rain, the match went ahead.|Cụm giới từ “in spite of + danh từ” đứng đầu câu, sau đó là mệnh đề chính.\no|She is in charge of training all the new nurses.|“In charge of” là cụm cố định, theo sau là V-ing “training” làm tân ngữ của giới từ.","verb-patterns-advanced":"c|I'll never forget ___ the sea for the first time; it was breathtaking.|seeing / to see / see / to have seen|0|“Forget + V-ing” nói về việc đã xảy ra mà mình nhớ mãi; “it was breathtaking” cho thấy đây là một kỷ niệm đã qua.|to see=>“Forget to see” nghĩa là quên không làm; câu này nói về ký ức đã xảy ra nên cần V-ing.;;see=>Sau forget không dùng V nguyên mẫu trần, câu cần dạng V-ing để nói về kỷ niệm trong quá khứ.;;to have seen=>Dạng hoàn thành sau forget nghe không tự nhiên ở đây; V-ing đơn giản đã diễn tả ký ức đủ rõ.\nc|Please remember ___ the lights before you leave the lab tonight.|switching off / to switch off / switch off / having switched off|1|“Remember + to V” là nhớ để làm việc cần làm; “before you leave” cho thấy việc tắt đèn còn ở phía trước.|switching off=>“Remember + V-ing” là nhớ việc đã làm, còn ở đây việc tắt đèn chưa xảy ra.;;switch off=>Sau remember không dùng V nguyên mẫu trần; cần “to V” hoặc V-ing tùy nghĩa của câu.;;having switched off=>Dạng hoàn thành chỉ việc đã xong, trong khi lời nhắc nói về việc sẽ làm trước khi rời phòng.\nc|He did not stop at the first degree; he went on ___ a doctorate and then a professorship.|earning / earn / to earn / to earning|2|“Go on + to V” nghĩa là sau đó làm tiếp một việc khác; bằng tiến sĩ và giáo sư là các bước mới sau bằng đầu tiên.|earning=>“Go on + V-ing” là tiếp tục làm cùng một việc, nhưng ở đây anh ấy chuyển sang việc mới.;;earn=>Sau go on không dùng V nguyên mẫu trần, cần dạng “to V” hoặc V-ing theo nghĩa.;;to earning=>Sau “go on to” phải là động từ nguyên mẫu; “to earning” không tạo thành cấu trúc đúng.\nc|I'm so tired of the noise. Will you please stop ___ that drum?|to play / play / to be playing / playing|3|“Stop + V-ing” là ngừng hẳn hành động đang làm; người nói đang phàn nàn về tiếng ồn nên muốn tiếng trống dừng lại.|to play=>“Stop to play” nghĩa là dừng lại để chơi, trái hẳn với ý muốn người kia ngừng chơi.;;play=>Sau stop không dùng V nguyên mẫu trần; cần V-ing để diễn tả hành động bị ngừng.;;to be playing=>Dạng này không đi sau stop và làm câu nặng nề, không diễn tả việc ngừng một hành động.\nc|Through the window I watched the children ___ the whole wall before the teacher noticed.|paint / painted / to paint / to be painting|0|Watch + O + V nguyên mẫu diễn tả hành động trọn vẹn từ đầu đến cuối; “the whole wall” cho thấy họ sơn xong cả bức tường.|painted=>Dạng quá khứ phân từ không dùng sau watch + tân ngữ để chỉ người thực hiện hành động.;;to paint=>Sau động từ tri giác trong câu chủ động, V nguyên mẫu không có “to”.;;to be painting=>Cấu trúc này không dùng sau watch + tân ngữ; cần V nguyên mẫu hoặc V-ing.\nc|Your hair is so long that it really needs ___.|cut / cutting / to cut / to be cutting|1|“Need + V-ing” mang nghĩa bị động (cần được cắt); chủ ngữ là “hair”, một vật chịu tác động nên dùng V-ing.|cut=>Sau need, V nguyên mẫu trần không đúng; cần “to be cut” hoặc V-ing mang nghĩa bị động.;;to cut=>“To cut” mang nghĩa chủ động, nhưng tóc là vật được cắt chứ không tự đi cắt.;;to be cutting=>Dạng tiếp diễn chủ động không diễn tả được việc tóc cần được người khác cắt.\nc|After such a long trial, the volunteers deserve ___ for their effort.|thanking / to thank / to be thanked / being thanked|2|“Deserve + to be V-ed” nghĩa là xứng đáng được làm gì; tình nguyện viên nhận lời cảm ơn nên cần dạng bị động.|thanking=>Chủ ngữ là người nhận lời cảm ơn, nên V-ing chủ động không diễn tả đúng ý bị động.;;to thank=>Dạng chủ động nghĩa là họ xứng đáng đi cảm ơn người khác, không phải được cảm ơn.;;being thanked=>Sau deserve dùng “to be V-ed”, không dùng “being V-ed” trong cấu trúc bị động này.\nc|Many new residents have difficulty ___ the local dialect.|to understand / understand / understood / understanding|3|“Have difficulty (in) + V-ing” là mẫu cố định; “new residents” là người gặp khó nên dùng V-ing chủ động.|to understand=>Sau “have difficulty” đi với V-ing hoặc “in + V-ing”, không dùng “to V”.;;understand=>V nguyên mẫu trần không đi sau “have difficulty”; cần dạng V-ing.;;understood=>Quá khứ phân từ mang nghĩa bị động, không hợp để chỉ việc cư dân gặp khó khi hiểu.\nc|Students often waste hours ___ through social media instead of revising.|scrolling / to scroll / scroll / for scrolling|0|“Waste/spend + thời gian + V-ing” là mẫu cố định; “hours” là cụm chỉ thời gian bị lãng phí.|to scroll=>Sau waste time dùng V-ing, không dùng “to V” để chỉ cách tiêu phí thời gian.;;scroll=>V nguyên mẫu trần không đi sau “waste hours” trong mẫu này.;;for scrolling=>Giới từ “for” thừa; waste/spend time đi thẳng với V-ing không cần giới từ.\nc|The accountant admitted ___ the records, but he denied stealing any money.|to alter / altering / alter / having to alter|1|Admit và deny đều đi với V-ing; “denied stealing” song song với “admitted altering” cho thấy cùng một mẫu.|to alter=>Sau admit không dùng “to V” để nói về việc đã làm; cần V-ing.;;alter=>V nguyên mẫu trần không đi sau admit trong cấu trúc này.;;having to alter=>Cụm này nghĩa là bị buộc phải sửa, không phải thừa nhận đã sửa.\nc|My parents never made me ___ a career in medicine.|to choose / choosing / choose / chosen|2|Make + O + V nguyên mẫu (không “to”) diễn tả sự bắt buộc; “never made me choose” là cha mẹ không ép tôi chọn.|to choose=>Sau make + tân ngữ trong câu chủ động dùng V nguyên mẫu không có “to”.;;choosing=>V-ing không đi sau make + tân ngữ để diễn tả sự ép buộc.;;chosen=>Quá khứ phân từ làm câu sai nghĩa; ở đây cần hành động chủ động của “me”.\nc|The new software helps researchers ___ data much faster.|analysing / analysed / to analysing / to analyse|3|Help + O + (to) V; vì phần mềm giúp nhà nghiên cứu phân tích, cần dạng nguyên mẫu “to analyse” trong các lựa chọn.|analysing=>Sau help + tân ngữ dùng V nguyên mẫu (có hoặc không “to”), không dùng V-ing.;;analysed=>Quá khứ phân từ mang nghĩa bị động, không hợp khi nhà nghiên cứu là người phân tích.;;to analysing=>“To” trong cấu trúc help là dấu hiệu nguyên mẫu nên không đi với V-ing.\nc|She resents ___ like a child by her colleagues.|being treated / to treat / treating / to be treated|0|Resent đi với V-ing; “by her colleagues” cho thấy cô ấy là người bị đối xử nên cần dạng bị động “being treated”.|to treat=>Chủ ngữ là người bị đối xử, nên dạng chủ động “to treat” sai nghĩa và sai mẫu sau resent.;;treating=>V-ing chủ động nghĩa là cô ấy đối xử với người khác, trong khi “by her colleagues” cho thấy bị động.;;to be treated=>Sau resent dùng V-ing, nên “to be treated” không đúng mẫu dù mang nghĩa bị động.\nc|I'm delighted ___ a place on the course; I applied three months ago.|to have given / to have been given / having given / to give|1|Sau tính từ cảm xúc dùng “to V”; tôi là người nhận suất học và việc đó đã xong nên dùng “to have been given”.|to have given=>Dạng chủ động nghĩa là tôi đã trao chỗ cho người khác, trái ý câu.;;having given=>Cụm này cũng mang nghĩa chủ động và không hợp sau tính từ delighted trong câu này.;;to give=>Dạng chủ động nguyên mẫu nghĩa là tôi trao đi, trong khi tôi mới là người nhận suất học.\nc|The board decided to postpone ___ the new policy until spring.|to introduce / introduce / introducing / to be introducing|2|Postpone + V-ing là mẫu cố định; cần phân biệt với “decided to postpone” ở đầu câu.|to introduce=>Postpone đi với V-ing, không đi với “to V”, dù decide thì dùng “to V”.;;introduce=>V nguyên mẫu trần không đi sau postpone trong câu này.;;to be introducing=>Dạng tiếp diễn nguyên mẫu không đi sau postpone và làm câu sai mẫu.\nc|Accepting the job would mean ___ to Berlin, so think carefully.|to move / move / having moved / moving|3|“Mean + V-ing” nghĩa là kéo theo hệ quả; nhận việc sẽ dẫn đến việc phải chuyển đến Berlin.|to move=>“Mean to V” nghĩa là có ý định, còn ở đây ý là hệ quả kéo theo của việc nhận việc.;;move=>V nguyên mẫu trần không đi sau mean trong câu này.;;having moved=>Dạng hoàn thành nói về việc đã xảy ra, nhưng việc chuyển nhà còn ở tương lai.\nc|The room was stuffy, so I tried ___ the window, and it cooled down at once.|opening / to open / open / having opened|0|“Try + V-ing” là thử một cách làm để xem kết quả; “it cooled down” là kết quả của việc thử mở cửa sổ.|to open=>“Try to V” là cố gắng, nhưng ở đây cửa sổ mở được và kết quả là phòng mát hơn.;;open=>V nguyên mẫu trần không đi sau try trong câu này.;;having opened=>Dạng hoàn thành không dùng sau try để chỉ việc thử một cách làm.\nc|On her way home, she stopped ___ some bread at the market.|buying / to buy / buy / having bought|1|“Stop + to V” nghĩa là dừng việc đang làm để làm việc khác; “on her way home” nói cô dừng chân để mua bánh mì.|buying=>“Stop + V-ing” nghĩa là ngừng việc mua, trong khi cô ấy dừng lại để đi mua.;;buy=>V nguyên mẫu trần không đi sau stop; cần “to V” để chỉ mục đích dừng lại.;;having bought=>Dạng hoàn thành nghĩa là đã mua xong, không diễn tả mục đích của việc dừng lại.\nc|As I passed the lab, I noticed a technician ___ with a pipette, so I did not disturb him.|struggled / to struggle / struggling / to be struggling|2|Notice + O + V-ing diễn tả hành động đang diễn ra khi mình đi ngang; “as I passed” cho thấy tôi chỉ thấy một phần.|struggled=>Quá khứ đơn không dùng làm bổ ngữ sau noticed + tân ngữ trong cấu trúc này.;;to struggle=>Sau động từ tri giác + tân ngữ không dùng “to V” trong câu chủ động.;;to be struggling=>Cấu trúc này không đi sau noticed + tân ngữ, cần V-ing hoặc V nguyên mẫu.\nc|The patient was made ___ for two hours before anyone examined him.|wait / waiting / waited / to wait|3|Chủ động: made him wait; bị động: was made to wait, vì “to” xuất hiện lại khi make ở dạng bị động.|wait=>Ở dạng bị động, make phải có “to” sau đó; V nguyên mẫu trần chỉ dùng ở dạng chủ động.;;waiting=>V-ing không đi sau “was made” trong mẫu bị động của make.;;waited=>Quá khứ không đi sau “was made” và làm câu sai cấu trúc.\nx|Chọn câu đúng|The students were made to rewrite the essay. / The students were made rewrite the essay. / The students were made rewriting the essay. / The students were made for rewrite the essay.|0|Make ở dạng bị động cần “to V” phía sau, trong khi chủ động là “made the students rewrite”.|The students were made rewrite the essay.=>Thiếu “to” sau “were made”; V nguyên mẫu trần chỉ đúng ở câu chủ động.;;The students were made rewriting the essay.=>V-ing không đi sau make ở cả chủ động lẫn bị động trong nghĩa bắt buộc.;;The students were made for rewrite the essay.=>“For” thừa và không dùng cùng nguyên mẫu để chỉ sự bắt buộc.\nt|She spent the whole weekend ___ (revise) for the final exam.|revising|Spend + thời gian + V-ing là mẫu cố định, nên “revise” phải chuyển thành V-ing.\nt|The committee considered ___ (postpone) the vote until after the holiday.|postponing|Consider đi với V-ing khi nghĩa là cân nhắc làm gì, nên dùng “postponing”.\nt|I clearly remember ___ (post) the letter, so it must be in the mail.|posting|Nhớ việc đã làm dùng remember + V-ing; “so it must be in the mail” xác nhận việc đã xảy ra.\nt|The residents deserve ___ (inform) about the changes much earlier.|to be informed|Deserve + to be V-ed diễn tả việc xứng đáng được làm gì; cư dân là người nhận thông tin.\nt|He admitted ___ (leave) the door unlocked when he went out.|leaving;to leaving;having left|Admit đi với V-ing, hoặc dạng hoàn thành “having left” khi nhấn mạnh việc đã xảy ra trước.\nf|He risked lose his job by arriving late three days in a row.|lose|losing|Risk là động từ đi với V-ing, nên “lose” phải chuyển thành “losing”.\nf|The old windows need clean before the visitors arrive on Monday.|clean|cleaning|Need mang nghĩa bị động cần V-ing (hoặc to be V-ed); “clean” trần là sai.\nf|The guards made him sit outside, and he was made wait for two hours.|wait|to wait|Ở dạng bị động “was made” phải có “to” trước động từ nguyên mẫu; chỉ vế chủ động mới không có “to”.\nf|We spent two hours discuss the budget without reaching a decision.|discuss|discussing|Sau spend + thời gian phải dùng V-ing, nên “discuss” cần đổi thành “discussing”.\no|She resents being treated like a child by her colleagues.|Resent + being V-ed (bị động), sau đó là cụm like a child và tác nhân bằng by.\no|I will never forget meeting the Prime Minister at the conference.|Forget + V-ing nói về ký ức đã xảy ra; phần địa điểm đặt cuối câu.\nx|Chọn câu đúng|I'll never forget to meet the Queen at school. / I'll never forget meeting the Queen at school. / I'll never forget meet the Queen at school. / I'll never forget to be meeting the Queen at school.|1|Khi nói về ký ức của một việc đã xảy ra, ta dùng forget + V-ing: “forget meeting”, còn “forget to V” chỉ việc quên không làm.|I'll never forget to meet the Queen at school.=>“forget to meet” nghĩa là quên không đi gặp, trong khi câu muốn nói đến ký ức về lần đã gặp nên phải dùng V-ing.;;I'll never forget meet the Queen at school.=>Sau “forget” không dùng động từ nguyên mẫu không “to”; cần V-ing cho ký ức hoặc to V cho việc quên làm.;;I'll never forget to be meeting the Queen at school.=>Dạng “to be meeting” nói về việc đang diễn ra trong tương lai, không diễn tả ký ức về một lần gặp đã xảy ra.\nx|Chọn câu đúng|I heard the door to slam and someone to run down the stairs. / I heard the door slamming and someone to run down the stairs. / I heard the door slam and someone run down the stairs. / I heard the door to slam and someone run down the stairs.|2|Sau động từ tri giác như “hear” ta dùng tân ngữ + động từ nguyên mẫu không “to” (nghe trọn hành động) hoặc + V-ing (nghe đang diễn ra).|I heard the door to slam and someone to run down the stairs.=>Sau “heard” trong cấu trúc chủ động không dùng “to” trước động từ; cả “to slam” và “to run” đều sai.;;I heard the door slamming and someone to run down the stairs.=>Vế đầu dùng được V-ing nhưng vế sau “someone to run” thêm “to” không đúng sau động từ tri giác chủ động.;;I heard the door to slam and someone run down the stairs.=>Vế sau đúng nhưng vế đầu “the door to slam” thêm “to” không đúng sau “heard” ở dạng chủ động.\nx|Chọn câu đúng|The windows need to clean before the guests arrive. / The windows need cleaning before the guests arrive. / The windows need clean before the guests arrive. / The windows need to cleaning before the guests arrive.|1|Khi chủ ngữ là vật cần được làm gì, ta dùng need + V-ing (nghĩa bị động) hoặc need to be + V3: “need cleaning” hay “need to be cleaned”.|The windows need to clean before the guests arrive.=>“need to clean” mang nghĩa chủ động, như thể cửa sổ tự lau; ở đây cần nghĩa bị động nên dùng V-ing hoặc to be cleaned.;;The windows need clean before the guests arrive.=>“need” không đi trực tiếp với tính từ hay động từ nguyên mẫu không “to” trong nghĩa này; cần V-ing hoặc to be V3.;;The windows need to cleaning before the guests arrive.=>Không kết hợp “to” với V-ing sau “need”; chọn một trong hai: need cleaning hoặc need to be cleaned."};
  const THEORY = {"complex-noun-phrases":{"summary":"Cụm danh từ phức gồm danh từ trung tâm cùng các thành phần đứng trước (tiền bổ nghĩa) và sau (hậu bổ nghĩa), cho phép nén nhiều thông tin vào một đơn vị ngữ pháp.","formulas":[{"label":"Tiền bổ nghĩa nhiều lớp","pattern":"determiner + adverb + adjective/V-ed + noun modifier + HEAD NOUN","ex":"a recently published, widely cited research report"},{"label":"Danh từ + of-phrase","pattern":"noun + of + noun phrase","ex":"the rapid growth of urban populations"},{"label":"Danh từ + cụm giới từ","pattern":"noun + preposition + noun phrase","ex":"a solution to the shortage of nurses"},{"label":"Danh từ + mệnh đề quan hệ","pattern":"noun + who/which/that + clause","ex":"a policy that limits access to treatment"},{"label":"Danh từ + to-infinitive","pattern":"noun + to V","ex":"the ability to work under pressure"},{"label":"Danh từ + V-ing / V-ed","pattern":"noun + V-ing / V-ed (+ complement)","ex":"students attending evening classes; the drugs prescribed to elderly patients"}],"uses":[{"title":"Gộp nhiều mệnh đề thành một cụm","detail":"Thay vì hai câu, đưa thông tin phụ vào bổ nghĩa cho danh từ.","ex":"Schools offering free meals saw higher attendance.","exvi":"Những trường cung cấp bữa ăn miễn phí có tỷ lệ đi học cao hơn."},{"title":"Hậu bổ nghĩa bằng V-ed","detail":"V-ed sau danh từ mang nghĩa bị động và rút gọn mệnh đề quan hệ.","ex":"The data collected in 2020 were incomplete.","exvi":"Số liệu thu thập năm 2020 chưa đầy đủ."},{"title":"Danh từ đi với to-infinitive hoặc of","detail":"Một số danh từ đòi hỏi bổ ngữ để nói rõ nội dung.","ex":"Her failure to respond caused serious delays.","exvi":"Việc cô ấy không phản hồi đã gây chậm trễ nghiêm trọng."},{"title":"Danh từ ghép làm bổ nghĩa","detail":"Danh từ đứng trước danh từ chính, thường ở dạng số ít.","ex":"A government health care policy review was announced.","exvi":"Một cuộc rà soát chính sách chăm sóc sức khoẻ của chính phủ đã được công bố."},{"title":"Phong cách khách quan, học thuật","detail":"Cụm danh từ dài đứng làm chủ ngữ giúp văn bản trang trọng, súc tích.","ex":"The widespread use of antibiotics has led to resistance.","exvi":"Việc sử dụng kháng sinh rộng rãi đã dẫn đến tình trạng kháng thuốc."}],"signals":["a number of","the decision to","the ability to","a solution to","an increase in","patients treated","the use of","recently introduced"],"cautions":["Đừng chồng quá nhiều bổ nghĩa: cụm dài khó đọc, hãy tách câu khi người đọc phải đọc lại.","Danh từ ghép: danh từ đứng trước thường số ít (“a car park”, “a ten-year plan”), không thêm -s.","V-ed/V-ing sau danh từ phải khớp nghĩa chủ động/bị động với mệnh đề quan hệ rút gọn.","Cụm này không phải danh từ hoá động từ (đã học riêng) và không phải trật tự tính từ cơ bản."]},"emphasis-structures":{"summary":"Nhấn mạnh trong tiếng Anh dùng trợ động từ do, đại từ phản thân, so/such, mệnh đề What/All và các trạng từ tăng cường để làm nổi bật ý cần nói.","formulas":[{"label":"Do/does/did nhấn mạnh","pattern":"S + do/does/did + V (nguyên mẫu)","ex":"She does know the answer, but she won't say."},{"label":"Đại từ phản thân nhấn mạnh","pattern":"N + oneself / S + V + O + oneself","ex":"The minister herself visited the clinic."},{"label":"So / such / what a","pattern":"so + adj / such + a + adj + N / What a + N!","ex":"What a remarkable recovery she has made!"},{"label":"Mệnh đề What / All","pattern":"What + S + V + is/was + N/to V; All + S + V + is (to) V","ex":"All I want is to finish this report."},{"label":"Phủ định nhấn mạnh","pattern":"by no means / not in the least / not at all / absolutely no + N","ex":"I was not in the least surprised by the news."},{"label":"Trạng từ tăng cường","pattern":"far too / much too / absolutely + adj; utterly, completely","ex":"The proposal is far too expensive for us."}],"uses":[{"title":"Sửa lại hiểu lầm","detail":"Dùng do/does/did để khẳng định điều người nghe tưởng là sai.","ex":"I did send the invoice; check your junk folder.","exvi":"Tôi có gửi hóa đơn rồi; hãy kiểm tra thư rác."},{"title":"Chỉ rõ chính người đó","detail":"Đại từ phản thân đứng sau danh từ để nhấn mạnh chính người hoặc vật ấy.","ex":"The patient herself asked for a second opinion.","exvi":"Chính bệnh nhân đã xin ý kiến thứ hai."},{"title":"Bộc lộ cảm xúc","detail":"So, such và what a thể hiện sự ngạc nhiên hoặc đánh giá mạnh.","ex":"It was such a relief to hear the results.","exvi":"Nghe được kết quả thật là nhẹ nhõm."},{"title":"Làm nổi bật thông tin chính","detail":"Mệnh đề What/All đặt phần quan trọng nhất ở cuối câu.","ex":"What worries me is the lack of funding.","exvi":"Điều khiến tôi lo là thiếu kinh phí."},{"title":"Phủ định mạnh","detail":"Cụm phủ định nhấn mạnh loại trừ hoàn toàn một ý.","ex":"She is by no means a beginner.","exvi":"Cô ấy hoàn toàn không phải người mới bắt đầu."}],"signals":["did","herself","himself","so","such","what a","What I need is","All I want is","by no means","not in the least"],"cautions":["Sau do/does/did nhấn mạnh luôn dùng động từ nguyên mẫu: “I did tell”, không phải “I did told”.","Đại từ phản thân nhấn mạnh có thể bỏ đi mà câu vẫn đủ nghĩa; đừng nhầm với tân ngữ phản thân như “She hurt herself”.","Khi viết, dùng chữ nghiêng hoặc cấu trúc thay vì viết hoa toàn bộ; đừng lạm dụng vì sẽ mất tác dụng nhấn mạnh.","Không nhầm với “It is ... that” (câu chẻ) và đảo ngữ với trạng từ phủ định, hai điểm này đã học riêng."]},"modals-advanced":{"summary":"Động từ khuyết thiếu nâng cao cho phép bạn diễn đạt độ chắc chắn, sự phê bình, quy định và thói quen một cách tinh tế hơn qua các dạng hoàn thành, tiếp diễn và các cấu trúc đặc biệt.","formulas":[{"label":"Modal + tiếp diễn (hiện tại)","pattern":"modal + be + V-ing","ex":"She may be working late at the lab."},{"label":"Modal + hoàn thành tiếp diễn","pattern":"modal + have been + V-ing","ex":"They should have been waiting outside."},{"label":"Không cần làm (đã làm rồi)","pattern":"needn't have + V3","ex":"You needn't have brought a gift."},{"label":"Sắp xếp / mệnh lệnh","pattern":"be to + V","ex":"Staff are to report to reception by nine."},{"label":"Lựa chọn hợp lý, giả định","pattern":"may well / might as well / would rather + V","ex":"We might as well wait for the results."},{"label":"Thói quen và đặc điểm","pattern":"will / would + V","ex":"When he was a student, he would study until dawn."}],"uses":[{"title":"Suy đoán hành động đang diễn ra","detail":"Dùng modal + be + V-ing để nói điều có thể đang xảy ra ngay lúc này.","ex":"The surgeon must be operating now.","exvi":"Bác sĩ phẫu thuật chắc hẳn đang mổ lúc này."},{"title":"Phê bình việc đã không làm","detail":"Dùng should/ought to have been + V-ing để trách việc lẽ ra đang diễn ra.","ex":"You ought to have been revising for the exam.","exvi":"Lẽ ra bạn phải đang ôn thi."},{"title":"Không cần mà vẫn làm","detail":"Needn't have + V3 nói hành động đã xảy ra nhưng thật ra không cần thiết.","ex":"I needn't have taken an umbrella.","exvi":"Lẽ ra tôi không cần mang ô."},{"title":"Quy định và sắp xếp","detail":"Shall và be to dùng cho quy định trang trọng, lệnh hoặc lịch đã định.","ex":"The tenant shall pay rent monthly.","exvi":"Người thuê nhà phải trả tiền thuê hằng tháng."},{"title":"Thói quen và đặc điểm","detail":"Will chỉ hành vi điển hình ở hiện tại, would chỉ thói quen trong quá khứ.","ex":"She will talk for hours about her patients.","exvi":"Cô ấy có thể nói hàng giờ về bệnh nhân của mình."}],"signals":["may well","might as well","would rather","needn't have","be to","dare","ought to have","shall"],"cautions":["Sau needn't, dare và need (khuyết thiếu) dùng động từ không “to”: “needn't go”.","“Didn't need to go” nói không cần đi (có thể đã đi hoặc không); “needn't have gone” chắc chắn đã đi.","“Will” chỉ thói quen cần trọng âm khi nói; “would” chỉ thói quen quá khứ không dùng cho trạng thái.","“Can't have + V3” chỉ suy luận về quá khứ, đã có trong phần suy đoán; ở đây tập trung vào dạng tiếp diễn."]},"passive-advanced":{"summary":"Bị động nâng cao mở rộng sang động từ khuyết thiếu, nguyên mẫu, danh động từ, cụm động từ, động từ hai tân ngữ và cấu trúc nhờ vả để viết trang trọng và chính xác.","formulas":[{"label":"Bị động với động từ khuyết thiếu","pattern":"modal + be + V3 / modal + have been + V3","ex":"The report ought to have been submitted by Friday."},{"label":"Nguyên mẫu và danh động từ bị động","pattern":"to be + V3 / to have been + V3 / being + V3","ex":"He expects to be promoted; she resents having been overlooked."},{"label":"Cụm động từ và động từ giới từ","pattern":"be + V3 + particle/preposition","ex":"The meeting was put off because the budget had not been dealt with."},{"label":"Have/get something done","pattern":"have/get + object + V3","ex":"We are having the roof replaced next month."},{"label":"Động từ hai tân ngữ","pattern":"person + be + V3 + object / object + be + V3 + to/for + person","ex":"A prize was given to the winner."},{"label":"Cấu trúc vô nhân xưng","pattern":"It + be + V3 + that-clause","ex":"It is expected that fees will rise."}],"uses":[{"title":"Văn phong trang trọng","detail":"Bị động giúp tránh nêu tác nhân khi không quan trọng hoặc không rõ.","ex":"All applications must be submitted online.","exvi":"Mọi hồ sơ phải được nộp trực tuyến."},{"title":"Thông tin mới ở cuối câu","detail":"Chỉ dùng by-agent khi tác nhân là thông tin mới hoặc quan trọng.","ex":"The vaccine was developed by a team in Leeds.","exvi":"Vắc-xin được phát triển bởi một nhóm ở Leeds."},{"title":"Sau động từ khuyết thiếu và dạng nguyên mẫu","detail":"Dùng modal + be V3 hoặc to be V3 cho nghĩa bị động trong nhiều cấu trúc.","ex":"Patients need to be monitored closely.","exvi":"Bệnh nhân cần được theo dõi sát sao."},{"title":"Dịch vụ do người khác làm","detail":"Have/get something done chỉ việc ta nhờ người khác làm hoặc trải qua điều không hay.","ex":"She had her car stolen outside the clinic.","exvi":"Cô ấy bị mất xe ngay trước phòng khám."},{"title":"Động từ hai tân ngữ","detail":"Chọn tân ngữ làm chủ ngữ tùy thông tin muốn nhấn mạnh.","ex":"He was offered a place at the university.","exvi":"Anh ấy được mời một suất học tại trường đại học."},{"title":"Quan điểm chung vô nhân xưng","detail":"It is said/thought... giúp nêu ý kiến chung mà không nêu ai.","ex":"It is widely believed that sleep aids memory.","exvi":"Nhiều người tin rằng giấc ngủ hỗ trợ trí nhớ."}],"signals":["must be","ought to have been","being","to have been","be dealt with","be put off","have it done","get it done","is expected that","by"],"cautions":["Cụm động từ và động từ giới từ không được tách trạng từ/giới từ ra khỏi động từ: “was looked after”, không phải “was looked”.","Nội động từ như “happen”, “occur”, “arrive” không có dạng bị động: “The accident was happened” là sai.","“Have something done” khác “be done”: chủ ngữ là người nhờ làm hoặc chịu hậu quả, ví dụ “I had my bag stolen”.","Không thêm “by people/someone” vô nghĩa; bỏ tác nhân khi nó hiển nhiên."]},"prepositional-phrases":{"summary":"Nhiều cụm giới từ là khối cố định: giới từ, mạo từ và danh từ đi cùng nhau nên phải học cả cụm thay vì ghép từng từ.","formulas":[{"label":"Giới từ + danh từ không mạo từ","pattern":"in / at / on / by / under + noun (no article)","ex":"She travels to work by train and is under pressure."},{"label":"Cụm giới từ trang trọng","pattern":"in terms of / with regard to / on behalf of / in view of + noun","ex":"On behalf of the staff, I would like to thank you."},{"label":"Giới từ phức chỉ nguyên nhân","pattern":"due to / owing to / as a result of / on account of + noun / V-ing","ex":"The match was postponed owing to heavy snow."},{"label":"Giới từ phức chỉ bổ sung, tương phản","pattern":"in addition to / apart from / instead of / in spite of + noun / V-ing","ex":"Apart from Lan, everyone passed the test."},{"label":"Danh từ + giới từ","pattern":"a rise in / an increase of / a solution to / a reason for","ex":"We need a solution to the staffing problem."},{"label":"Tính từ + giới từ","pattern":"aware of / subject to / prone to / liable to","ex":"The schedule is subject to change."}],"uses":[{"title":"Không mạo từ trong cụm cố định","detail":"Khi nói về chức năng của nơi chốn hay phương tiện, bỏ mạo từ.","ex":"He is in hospital, but his wife is at the hospital visiting him.","exvi":"Anh ấy đang nằm viện, còn vợ anh đang ở bệnh viện thăm anh."},{"title":"Giới từ phức trang trọng","detail":"Thay cho từ nối đơn giản để câu trang trọng hơn trong văn viết.","ex":"With regard to your enquiry, the course is full.","exvi":"Về câu hỏi của bạn, khóa học đã đầy."},{"title":"Nói về thay đổi số liệu","detail":"Dùng “a rise in” cho đối tượng tăng và “of” cho mức tăng.","ex":"There was a rise in sales of ten per cent.","exvi":"Doanh số đã tăng mười phần trăm."},{"title":"Sắc thái thời gian","detail":"Cặp gần nghĩa nhưng khác nhau: in time/on time, at the end/in the end, by/until.","ex":"We arrived in time to catch the early train.","exvi":"Chúng tôi đến kịp để bắt chuyến tàu sớm."},{"title":"Tình huống và trách nhiệm","detail":"Các cụm như at risk, in charge of, under pressure mô tả trạng thái.","ex":"Staff are under pressure to meet the deadline.","exvi":"Nhân viên chịu áp lực phải kịp hạn chót."}],"signals":["in terms of","with regard to","on behalf of","in the event of","owing to","due to","as a result of","apart from","in view of","by means of"],"cautions":["“Due to” thường đứng sau động từ be (“The delay was due to fog”); “owing to” đứng đầu câu hoặc sau động từ thường.","“Despite” và “in spite of” không thay lẫn dạng: “despite the rain”, “in spite of the rain”, không có “despite of”.","Sau giới từ phức dùng danh từ hoặc V-ing, không dùng mệnh đề: “due to the fact that…” mới đi với mệnh đề.","Cụm cố định không thể đổi giới từ: “in charge of”, “at risk”, “on foot”, “by car”."]},"verb-patterns-advanced":{"summary":"Nhiều động từ đổi nghĩa tùy theo theo sau là V-ing hay to V, và một số mẫu khác (tri giác, make/let/help, need + V-ing, bị động) có quy tắc riêng cần nhớ.","formulas":[{"label":"Việc đã xảy ra (V-ing)","pattern":"remember / forget / regret / stop / go on + V-ing","ex":"I remember locking the door, so it must be open now."},{"label":"Việc sắp làm (to V)","pattern":"remember / forget / regret / stop / go on / try + to V","ex":"Don't forget to submit the form by Friday."},{"label":"Động từ tri giác","pattern":"see / hear / watch / notice + O + V (xong) / V-ing (đang diễn ra)","ex":"I heard her sing the whole song / singing in the kitchen."},{"label":"Make / let / help","pattern":"make / let + O + V; help + O + (to) V; be made to V","ex":"The manager let the staff leave early."},{"label":"Need / want / deserve","pattern":"need / want + V-ing; deserve + to be V-ed","ex":"The garden wants watering; the team deserves to be praised."},{"label":"Động từ + V-ing cố định","pattern":"admit / deny / risk / avoid / consider / postpone / have difficulty (in) / spend time + V-ing","ex":"He denied taking the money and risked losing his job."}],"uses":[{"title":"Remember, forget, regret","detail":"V-ing nói về việc đã xảy ra trước; to V nói về việc cần làm hoặc thông báo ngay.","ex":"I regret not studying harder at university.","exvi":"Tôi tiếc vì đã không học chăm hơn ở đại học."},{"title":"Stop, try, go on, mean","detail":"Cùng động từ nhưng nghĩa khác nhau: dừng hẳn hay dừng để làm gì, thử nghiệm hay cố gắng.","ex":"Try taking a short break; it might help you concentrate.","exvi":"Hãy thử nghỉ ngơi một chút; có thể bạn sẽ tập trung hơn."},{"title":"Tri giác + tân ngữ","detail":"Dùng V nguyên mẫu cho hành động trọn vẹn, V-ing cho hành động đang diễn ra hoặc bị ngắt.","ex":"We watched the surgeon operate on the patient.","exvi":"Chúng tôi xem bác sĩ phẫu thuật mổ cho bệnh nhân."},{"title":"Need/want + V-ing","detail":"Nghĩa bị động: vật cần được làm gì đó; cũng dùng deserve + to be V-ed.","ex":"These documents need checking again.","exvi":"Những tài liệu này cần được kiểm tra lại."},{"title":"Make, let, help","detail":"Theo sau là tân ngữ và V nguyên mẫu; khi bị động make phải thêm “to”.","ex":"The heat made everyone feel exhausted.","exvi":"Cái nóng khiến mọi người cảm thấy kiệt sức."},{"title":"Dạng bị động của động từ","detail":"Dùng to be V-ed, being V-ed, to have been V-ed khi chủ ngữ là người nhận hành động.","ex":"She hates being asked personal questions.","exvi":"Cô ấy ghét bị hỏi những câu hỏi riêng tư."}],"signals":["remember","forget","regret","stop","try","go on","mean","need","deserve","avoid"],"cautions":["Sau make/let và động từ tri giác dùng V nguyên mẫu không “to”; nhưng bị động “was made to wait”.","“Mean + V-ing” nghĩa là kéo theo hệ quả, “mean + to V” là có ý định.","Sau “have difficulty (in)” và “spend time” dùng V-ing, không dùng “to V”.","Chủ đề cơ bản gerund/infinitive và động từ tường thuật đã học ở bài khác."]}};
  const GX_ADD = {"complex-noun-phrases":{"mistakes":[{"wrong":"The decision postponing the trial upset us.","right":"The decision to postpone the trial upset us.","bad":"postponing","fix":"to","why":"Sau “decision” dùng to-infinitive để nêu nội dung quyết định, không dùng V-ing."},{"wrong":"The data collecting in 2020 were incomplete.","right":"The data collected in 2020 were incomplete.","bad":"collecting","fix":"collected","why":"Dữ liệu được thu thập mang nghĩa bị động nên dùng V-ed sau danh từ, không dùng V-ing."},{"wrong":"Staffs shortage is a serious problem.","right":"Staff shortage is a serious problem.","bad":"Staffs","fix":"Staff","why":"Danh từ đứng trước trong danh từ ghép giữ số ít. Tiếng Việt không có số nhiều nên dễ thêm -s."},{"wrong":"She has a ten-years plan for the clinic.","right":"She has a ten-year plan for the clinic.","bad":"ten-years","fix":"ten-year","why":"Khi dùng như tính từ ghép trước danh từ, số đếm + danh từ giữ số ít: “a ten-year plan”."},{"wrong":"The patients treating last year recovered quickly.","right":"The patients treated last year recovered quickly.","bad":"treating","fix":"treated","why":"Bệnh nhân bị điều trị mang nghĩa bị động nên dùng V-ed, không dùng V-ing."},{"wrong":"There was an increase of the number of applicants.","right":"There was an increase in the number of applicants.","bad":"of","fix":"in","why":"“an increase in” nêu thứ gì tăng; “of” dùng khi nêu lượng tăng, như “an increase of 5%”."},{"wrong":"Students who study abroad they gain independence.","right":"Students who study abroad gain independence.","bad":"they","fix":"bỏ “they”","why":"Mệnh đề quan hệ đã có chủ ngữ “who”, không lặp thêm đại từ “they” như khi nói tiếng Việt."},{"wrong":"A solution of the problem was finally found.","right":"A solution to the problem was finally found.","bad":"of","fix":"to","why":"Danh từ “solution” đi với giới từ “to” khi nói về vấn đề được giải quyết."}],"contrast":{"title":"V-ing hay V-ed sau danh từ?","a":"noun + V-ing (chủ động)","b":"noun + V-ed (bị động)","rows":[["Nghĩa","Danh từ thực hiện hành động: “the staff working nights”.","Danh từ chịu hành động: “the staff employed last year”."],["Tương đương mệnh đề quan hệ","“who/which + V” (“who work”).","“who/which + be + V-ed” (“who were employed”)."],["Thời gian","Thường chỉ việc đang hoặc luôn xảy ra.","Thường chỉ việc đã xảy ra, đã hoàn tất."],["Dấu hiệu nhận biết","Theo sau thường là tân ngữ: “a ward housing patients”.","Theo sau thường là giới từ hoặc trạng từ: “damaged in the storm”."]],"ex":[["Students attending the lecture took notes.","Students invited to the lecture took notes."],["A study exploring sleep was published.","A study conducted last year was published."]],"tip":"Danh từ làm việc thì V-ing, danh từ bị tác động thì V-ed: thử thêm “who/which” để kiểm tra.","quiz":[{"q":"The nurses ___ the new protocol reported fewer errors.","opts":["following","followed","to follow","are following"],"a":0,"why":"Y tá chủ động làm theo quy trình nên dùng V-ing: “nurses following the new protocol”.","wrong":{"followed":"V-ed mang nghĩa bị động, trong khi y tá chủ động làm theo quy trình.","to follow":"To-infinitive nêu mục đích hoặc tương lai, không hợp với việc đã báo cáo.","are following":"“are following” thêm một động từ chia thì nên câu có hai động từ chính."}},{"q":"The drugs ___ to elderly patients can cause dizziness.","opts":["prescribing","prescribed","to prescribe","prescribe"],"a":1,"why":"Thuốc được kê cho bệnh nhân mang nghĩa bị động nên dùng V-ed: “drugs prescribed to elderly patients”.","wrong":{"prescribing":"V-ing mang nghĩa chủ động, nhưng thuốc không tự kê đơn cho ai.","to prescribe":"To-infinitive nói mục đích hoặc việc sẽ làm, không hợp với thuốc đã được kê.","prescribe":"“prescribe” là động từ chia thì và chồng với “can cause”, gây sai cấu trúc."}},{"q":"Any student ___ the exam will receive extra support.","opts":["failed","to fail","failing","who failing"],"a":2,"why":"Sinh viên trượt kỳ thi là người thực hiện hành động nên dùng V-ing: “any student failing the exam”.","wrong":{"failed":"V-ed mang nghĩa bị động, nhưng sinh viên tự thi trượt nên cần V-ing.","to fail":"To-infinitive đổi nghĩa thành sinh viên sắp trượt, không chỉ đối tượng được hỗ trợ.","who failing":"“who failing” thiếu trợ động từ nên sai cấu trúc quan hệ."}},{"q":"Several buildings ___ in the earthquake are still closed.","opts":["damaging","to damage","damage","damaged"],"a":3,"why":"Các toà nhà bị hư hại nên dùng V-ed sau danh từ: “buildings damaged in the earthquake”.","wrong":{"damaging":"V-ing mang nghĩa chủ động, trong khi các toà nhà bị động chịu thiệt hại.","to damage":"To-infinitive không hợp với sự việc đã xảy ra là trận động đất.","damage":"“damage” là động từ chia thì, chồng với “are still closed” nên sai."}},{"q":"A new ward ___ 40 patients opened in May.","opts":["housing","housed","to house","house"],"a":0,"why":"Khu nằm trong vai trò chủ động chứa 40 bệnh nhân, nên dùng V-ing: “a ward housing 40 patients”.","wrong":{"housed":"V-ed đổi thành khu bị chứa 40 bệnh nhân, nghĩa sai.","to house":"To-infinitive chỉ mục đích, trong khi khu này đã mở và chứa sẵn bệnh nhân.","house":"“house” là động từ chia thì và chồng với động từ chính “opened”."}},{"q":"Several studies ___ at the university suggest a link between stress and sleep.","opts":["conducting","conducted","to conduct","conduct"],"a":1,"why":"Nghiên cứu được tiến hành nên dùng V-ed sau danh từ: “studies conducted at the university”.","wrong":{"conducting":"V-ing mang nghĩa chủ động, nhưng các nghiên cứu được thực hiện bởi người khác.","to conduct":"To-infinitive nói mục đích, không hợp với việc đã làm xong tại trường.","conduct":"“conduct” là động từ chia thì và chồng với “suggest”, gây sai cấu trúc."}},{"q":"The report contained a number of ___ recommendations.","opts":["carefully wording","worded carefully","carefully worded","carefully words"],"a":2,"why":"Trạng từ + V-ed đứng trước danh từ làm tiền bổ nghĩa: “carefully worded recommendations”.","wrong":{"carefully wording":"V-ing mang nghĩa chủ động, trong khi kiến nghị được diễn đạt cẩn thận.","worded carefully":"Trạng từ đứng sau V-ed thì cụm này không đặt trước danh từ được.","carefully words":"“words” là danh từ, không kết hợp với trạng từ để bổ nghĩa như vậy."}},{"q":"Volunteers ___ the community garden meet every Saturday.","opts":["maintained","to maintain","are maintaining","maintaining"],"a":3,"why":"Tình nguyện viên là người thực hiện việc chăm sóc nên dùng V-ing: “volunteers maintaining the garden”.","wrong":{"maintained":"V-ed mang nghĩa bị động, nhưng tình nguyện viên chủ động chăm sóc khu vườn.","to maintain":"To-infinitive đổi nghĩa thành mục đích, không mô tả họ đang làm gì.","are maintaining":"“are maintaining” thêm động từ chia thì và làm câu có hai động từ chính."}}]}},"emphasis-structures":{"mistakes":[{"wrong":"I did went to the meeting yesterday.","right":"I did go to the meeting yesterday.","bad":"went","fix":"go","why":"Sau did nhấn mạnh dùng nguyên mẫu. Người Việt hay chia quá khứ hai lần: did + went."},{"wrong":"She does knows the answer already.","right":"She does know the answer already.","bad":"knows","fix":"know","why":"Does đã mang chia ngôi thứ ba số ít, nên động từ sau đó trở về nguyên mẫu."},{"wrong":"What I need it is a rest.","right":"What I need is a rest.","bad":"it","fix":"(bỏ)","why":"Mệnh đề What làm chủ ngữ, nên không thêm “it”. Tiếng Việt “cái mà tôi cần thì...” dễ khiến thêm đại từ thừa."},{"wrong":"It was so a nice day.","right":"It was such a nice day.","bad":"so","fix":"such","why":"Trước a + tính từ + danh từ dùng “such”; “so” chỉ đứng trước tính từ đơn: “so nice”."},{"wrong":"What a beautiful weather it is!","right":"What beautiful weather it is!","bad":"a","fix":"(bỏ)","why":"Weather là danh từ không đếm được nên không dùng “a” sau “What”. Tiếng Việt không có mạo từ nên dễ thêm."},{"wrong":"The doctor herself she signed the form.","right":"The doctor herself signed the form.","bad":"she","fix":"(bỏ)","why":"Đại từ phản thân nhấn mạnh đã thay vai nhấn mạnh, nên không lặp lại đại từ chủ ngữ."},{"wrong":"The film was not at the least boring.","right":"The film was not in the least boring.","bad":"at","fix":"in","why":"Cụm cố định là “not in the least”. Đừng nhầm với “not at all”."},{"wrong":"All I want are some peace and quiet.","right":"All I want is some peace and quiet.","bad":"are","fix":"is","why":"Mệnh đề All I want được coi là số ít, nên động từ là “is” dù danh từ phía sau có vẻ số nhiều."}],"contrast":{"title":"so hay such?","a":"so","b":"such","rows":[["Đi với từ loại nào","so + tính từ hoặc trạng từ: “so tired”, “so quickly”.","such + (a/an) + (tính từ) + danh từ: “such a long day”, “such problems”."],["Với danh từ số nhiều/không đếm được","Không dùng trực tiếp trước danh từ; cần thêm many/much: “so many people”.","Dùng trực tiếp: “such good advice”, “such difficult questions”."],["Với a/an","Thứ tự trang trọng: so + tính từ + a + danh từ: “so long a day”.","Thứ tự thường: such + a + tính từ + danh từ: “such a long day”."],["Câu cảm thán","“How tired I am!”, “so tired” khi nói nhấn mạnh.","“What a day!”, “such a day!”; What dùng với danh từ."]],"ex":[["I was so tired that I fell asleep at my desk.","It was such a tiring day that I fell asleep at my desk."],["The queue moved so slowly.","It was such a slow queue."]],"tip":"So bám tính từ, such bám danh từ: thấy a + danh từ thì chọn such.","quiz":[{"t":"c","q":"She was ___ exhausted that she could hardly speak.","opts":["so","such","too","very"],"a":0,"why":"So + tính từ + that chỉ kết quả; exhausted là tính từ đơn nên dùng so.","wrong":{"such":"Sau chỗ trống chỉ có tính từ “exhausted”, không có danh từ nên “such” không hợp.","too":"“Too” chỉ mức quá mức và không đi với “that” chỉ kết quả như vậy.","very":"“Very” không tạo cấu trúc kết quả với mệnh đề “that she could hardly speak”."}},{"t":"c","q":"It was ___ a surprising result that nobody believed it.","opts":["so","such","too","what"],"a":1,"why":"A + tính từ + danh từ đi với such; vế that chỉ kết quả.","wrong":{"so":"Sau chỗ trống là “a surprising result” (a + tính từ + danh từ), thì cần such, không dùng so.","too":"“Too” cần tính từ và không đứng trước mạo từ “a” trong cấu trúc này.","what":"“What” dùng cho câu cảm thán, còn ở đây là mệnh đề kết quả với “that”."}},{"t":"c","q":"They gave us ___ helpful advice that we changed our plan.","opts":["so","a","such","what"],"a":2,"why":"Such + tính từ + danh từ không đếm được, không cần mạo từ.","wrong":{"so":"“Advice” là danh từ, nên so không thể đứng thẳng trước “helpful advice”.","a":"“Advice” không đếm được nên không dùng “a” và cũng không có such đi kèm.","what":"“What” ở đây không tạo mệnh đề kết quả với “that we changed our plan”."}},{"t":"c","q":"There were ___ many people at the clinic that we left.","opts":["such","very","too","so"],"a":3,"why":"So many/much + danh từ + that là mẫu cố định; such không đi trước many.","wrong":{"such":"Such không đi với “many” trực tiếp; “such many people” là sai.","very":"“Very” không nối với mệnh đề kết quả “that we left”.","too":"“Too many” dùng với “to + V”, còn ở đây có mệnh đề “that”."}},{"t":"c","q":"Cô ấy đúng là một bác sĩ giỏi! — ___ a good doctor she is!","opts":["So","What","How","Such"],"a":1,"why":"What + a + tính từ + danh từ là mẫu cảm thán; “How good” mới đi với tính từ.","wrong":{"So":"“So a good doctor” sai thứ tự; so không đứng trước a + tính từ + danh từ trong câu cảm thán.","How":"“How” đi với tính từ hoặc trạng từ, không đi trước “a good doctor”.","Such":"Such dùng trong câu khẳng định kèm that; câu cảm thán mở đầu bằng What."}},{"t":"c","q":"The director ___ announced the merger, not the press office.","opts":["her","she","herself","own"],"a":2,"why":"Mệnh đề “not the press office” nhấn vào chính giám đốc nên dùng herself.","wrong":{"her":"Không dùng tân ngữ “her” làm chủ ngữ nhấn mạnh sau danh từ.","she":"Đại từ chủ ngữ lặp lại và không nhấn mạnh được chính người đó.","own":"“Own” cần tính từ sở hữu đi kèm và không đứng sau danh từ chủ ngữ."}},{"t":"c","q":"I ___ send the report on time, so please check your inbox again.","opts":["do","done","was","did"],"a":3,"why":"Did + V nhấn mạnh việc đã xảy ra; “check your inbox again” cho thấy người nghe nghi ngờ.","wrong":{"do":"Câu nói về việc đã gửi trong quá khứ nên không dùng “do” hiện tại.","done":"“Done” không đứng trước nguyên mẫu “send” để nhấn mạnh.","was":"“Was” không kết hợp với nguyên mẫu “send” để nhấn mạnh hành động."}},{"t":"c","q":"The plan is ___ means perfect, but it is a start.","opts":["by no","not in","in no","at no"],"a":0,"why":"By no means perfect = hoàn toàn không hoàn hảo; but it is a start xác nhận ý nhượng bộ.","wrong":{"not in":"Cụm này cần “the least” theo sau, không đi trước “means”.","in no":"Không có cụm “in no means” trong tiếng Anh chuẩn.","at no":"“At no” không tạo cụm “at no means” theo cách dùng thông thường."}}]}},"modals-advanced":{"mistakes":[{"wrong":"You needn't worrying about the fee.","right":"You needn't worry about the fee.","bad":"worrying","fix":"worry","why":"Needn't là khuyết thiếu nên theo sau là động từ nguyên mẫu không to, không dùng V-ing."},{"wrong":"He must be work in the lab now.","right":"He must be working in the lab now.","bad":"work","fix":"working","why":"Suy luận về việc đang diễn ra dùng “must be + V-ing”. Người Việt hay quên đuôi -ing sau “be”."},{"wrong":"We might as well waiting here.","right":"We might as well wait here.","bad":"waiting","fix":"wait","why":"Sau “might as well” dùng động từ nguyên mẫu không to, không dùng V-ing."},{"wrong":"I needn't have went there.","right":"I needn't have gone there.","bad":"went","fix":"gone","why":"Sau “needn't have” phải là quá khứ phân từ “gone”, không phải dạng quá khứ đơn “went”."},{"wrong":"Yesterday you should be waiting outside, not here.","right":"Yesterday you should have been waiting outside, not here.","bad":"be","fix":"have been","why":"Phê bình việc trong quá khứ cần “should have been + V-ing”; “yesterday” không đi với “should be”."},{"wrong":"When I was young, I will walk to school every day.","right":"When I was young, I would walk to school every day.","bad":"will","fix":"would","why":"Thói quen quá khứ dùng “would”; “will” chỉ thói quen ở hiện tại."},{"wrong":"The minister is to visits the school on Friday.","right":"The minister is to visit the school on Friday.","bad":"visits","fix":"visit","why":"Trong cấu trúc “be to + V”, động từ sau “to” luôn ở dạng nguyên mẫu, không thêm -s."},{"wrong":"He should have waiting outside the office.","right":"He should have been waiting outside the office.","bad":"","fix":"been","why":"Dạng hoàn thành tiếp diễn cần đủ “have been + V-ing”; thiếu “been” là lỗi hay gặp."}],"contrast":{"title":"needn't have hay didn't need to?","a":"needn't have + V3","b":"didn't need to + V","rows":[["Hành động có xảy ra không","Chắc chắn đã làm, nhưng thừa: “We needn't have left.”","Không rõ có làm hay không: “We didn't need to leave.”"],["Ngữ cảnh điển hình","Nhận ra sau khi làm là không cần thiết","Thông báo việc đó không bắt buộc ở quá khứ"],["Cấu trúc","Khuyết thiếu, không to: needn't have gone","Động từ thường: didn't need to go"]],"ex":[["You needn't have brought food; we had plenty.","You didn't need to bring food, so I came empty-handed."],["I needn't have hurried; the train was late.","I didn't need to hurry, so I walked slowly."]],"tip":"Needn't have = làm rồi mới biết thừa; didn't need to = chỉ nói không bắt buộc, có thể không làm.","quiz":[{"q":"The doctor was running late, so I ___ rushed to the clinic; I sat in the waiting room for an hour.","opts":["didn't need to have","needn't have","needn't","mustn't have"],"a":1,"why":"Việc vội đã xảy ra nhưng thừa, nên dùng needn't have + V3.","wrong":{"didn't need to have":"Didn't need to have rushed không phải cấu trúc tự nhiên, vì didn't need đi với to V.","needn't":"Needn't rushed sai vì thiếu have và dùng quá khứ.","mustn't have":"Mustn't have rushed là suy luận phủ định, không hợp nghĩa."}},{"q":"It was a holiday, so Maya ___ get up early; she slept until ten.","opts":["needn't have to","needn't have","didn't need to","needn't"],"a":2,"why":"Việc không cần và cũng không làm, nên dùng didn't need to.","wrong":{"needn't have to":"Needn't have to không tồn tại trong tiếng Anh chuẩn.","needn't have":"Needn't have + get dùng sai dạng, và ngụ ý đã dậy sớm.","needn't":"Needn't get nói về hiện tại, không hợp với quá khứ."}},{"q":"We booked a table, but the restaurant was empty. We ___ booked.","opts":["needn't have","didn't need","needn't","mustn't have"],"a":0,"why":"Việc đặt bàn đã xảy ra mà thừa, nên dùng needn't have + V3.","wrong":{"didn't need":"Didn't need booked sai ngữ pháp vì sau didn't need không dùng quá khứ phân từ.","needn't":"Needn't booked sai vì thiếu have trước quá khứ phân từ.","mustn't have":"Mustn't have booked mang nghĩa suy luận, không hợp tình huống."}},{"q":"Luckily, the form was optional, so students ___ fill it in.","opts":["needn't have","mustn't","didn't need to","needn't to"],"a":2,"why":"Không cần làm và nói chung chung ở quá khứ, dùng didn't need to.","wrong":{"needn't have":"Needn't have fill sai dạng vì sau have phải là V3.","mustn't":"Mustn't fill là cấm đoán, không đúng nghĩa tùy chọn.","needn't to":"Needn't to sai vì needn't không đi với to."}},{"q":"The patient ___ be asleep now; his monitor shows steady slow breathing.","opts":["can't have","may","should have","won't"],"a":1,"why":"May + be là khả năng ở hiện tại, khớp với dấu hiệu thở chậm đều.","wrong":{"can't have":"Can't have + V3 nói về quá khứ và phủ định khả năng.","should have":"Should have + V3 là phê bình việc quá khứ, không phải suy đoán.","won't":"Won't be không hợp vì nghĩa phủ định chắc chắn."}},{"q":"“___ I open the window?” asked the receptionist politely.","opts":["Shall","Must","Would","Need"],"a":0,"why":"Shall ở ngôi thứ nhất dùng để đề nghị.","wrong":{"Must":"Must I open là bắt buộc, không phải đề nghị.","Would":"Would I open sai nghĩa đề nghị.","Need":"Need I open nghe như hỏi có cần không, không lịch sự đề nghị."}},{"q":"My grandfather ___ tell us stories for hours when we visited him as children.","opts":["will","would","is to","shall"],"a":1,"why":"Would chỉ thói quen quá khứ, khớp với “as children”.","wrong":{"will":"Will chỉ thói quen hiện tại, sai thì.","is to":"Is to chỉ sắp xếp, không phải thói quen.","shall":"Shall là quy định trang trọng, không nói thói quen."}},{"q":"You ___ been revising last night instead of watching films.","opts":["ought to have","ought to be","should be","must have"],"a":0,"why":"Ought to have been + V-ing phê bình việc quá khứ, “last night” báo hiệu quá khứ.","wrong":{"ought to be":"Ought to be revising nói về hiện tại.","should be":"Should be revising nói về hiện tại.","must have":"Must have been revising suy luận rằng đã ôn, mâu thuẫn với phim."}}]}},"passive-advanced":{"mistakes":[{"wrong":"The report must submitted before Friday.","right":"The report must be submitted before Friday.","bad":"","fix":"be","why":"Thiếu “be”: động từ khuyết thiếu + be + V3 mới là bị động. Tiếng Việt “bị/được” không có chỗ cho “be” nên người học hay bỏ sót."},{"wrong":"The bridge was build in 1990 by local workers.","right":"The bridge was built in 1990 by local workers.","bad":"build","fix":"built","why":"Bị động cần V3: “was built”, không dùng nguyên mẫu “build”. Người Việt hay giữ nguyên động từ vì tiếng Việt không biến đổi."},{"wrong":"A prize was given for her by the school.","right":"A prize was given to her by the school.","bad":"for","fix":"to","why":"Với “give” bị động, người nhận đi với “to”, không dùng “for”. Nhớ: give something TO somebody."},{"wrong":"The problem was dealt of quickly by the team.","right":"The problem was dealt with quickly by the team.","bad":"of","fix":"with","why":"“Deal with” giữ nguyên giới từ “with” khi bị động. Đừng dịch giới từ theo tiếng Việt."},{"wrong":"He hates being asking the same question.","right":"He hates being asked the same question.","bad":"asking","fix":"asked","why":"Sau “being” phải là V3, không phải V-ing. “Being asked” nghĩa là bị hỏi, còn “asking” là đi hỏi."},{"wrong":"I had my car repair yesterday.","right":"I had my car repaired yesterday.","bad":"repair","fix":"repaired","why":"Cấu trúc have + vật + V3 nhờ ai làm gì. Người Việt hay dùng nguyên mẫu vì nghĩ “nhờ sửa”, nhưng phải là “repaired”."},{"wrong":"The meeting has been put up until next week.","right":"The meeting has been put off until next week.","bad":"up","fix":"off","why":"“Put off” nghĩa là hoãn, “put up” là dựng hoặc cho ở nhờ. Nhớ “off” như việc bị gạt ra khỏi lịch."},{"wrong":"The patient ought to been told the truth.","right":"The patient ought to have been told the truth.","bad":"","fix":"have","why":"Việc lẽ ra phải làm trong quá khứ dùng “ought to have been + V3”. Thiếu “have” là lỗi hay gặp."}],"contrast":{"title":"be + V3 hay have + vật + V3?","a":"be + V3 (bị động)","b":"have + vật + V3 (nhờ/chịu tác động)","rows":[["Ý nghĩa","Vật chịu tác động, người làm không quan trọng: “The car was repaired.”","Nhờ ai làm hoặc gặp chuyện không mong muốn: “I had my car repaired.”"],["Chủ ngữ","Chủ ngữ là vật hoặc người bị tác động","Chủ ngữ là người sở hữu hoặc người nhờ làm"],["Sắc thái","Trung tính, trang trọng, mô tả sự việc","Nhấn vào việc người đó sắp xếp hoặc chịu hậu quả"]],"ex":[["The windows were cleaned yesterday.","She had the windows cleaned yesterday."],["The documents were checked by an auditor.","We had the documents checked by an auditor."]],"tip":"Chỉ mô tả việc xảy ra thì dùng be + V3; chủ ngữ là người nhờ hoặc chịu thiệt thì dùng have + vật + V3.","quiz":[{"q":"I can't type this report myself, so I'm going to ___ by a secretary.","opts":["be typed","have it typing","have it typed","has it typed"],"a":2,"why":"“I'm going to ... by a secretary” là nhờ người khác làm, nên dùng have + it + V3.","wrong":{"be typed":"Chủ ngữ “I” không phải là bản báo cáo nên “be typed” sai; ở đây cần nhờ người khác làm.","have it typing":"Sau “have + vật” cần V3 “typed”, không dùng V-ing trong nghĩa nhờ làm.","has it typed":"Sau “going to” cần nguyên mẫu “have”; “has” sai dạng."}},{"q":"The new library ___ by the mayor last week.","opts":["was opened","had opened","had it opened","has been opened"],"a":0,"why":"Chủ ngữ là vật, có “by the mayor” và “last week” nên dùng quá khứ bị động “was opened”.","wrong":{"had opened":"“Had opened” là chủ động hoàn thành, nhưng thư viện không tự mở bằng thị trưởng.","had it opened":"Cấu trúc nhờ làm không hợp vì “library” là chủ ngữ, không phải người nhờ.","has been opened":"Hiện tại hoàn thành không hợp với “last week”, mốc thời gian xác định."}},{"q":"He ___ his phone stolen on the bus yesterday.","opts":["was","has been","got to","had"],"a":3,"why":"Have + vật + V3 cũng diễn tả chuyện không may xảy ra với mình; “yesterday” cho quá khứ nên dùng “had”.","wrong":{"was":"Sau “was” cần V3 chứ không phải “his phone stolen”; câu thành sai cấu trúc.","has been":"Không hợp với “yesterday” và không đi với “his phone stolen” theo nghĩa này.","got to":"“Got to” nghĩa là phải, không tạo nghĩa chịu thiệt hại trong câu này."}},{"q":"The old bridge ___ down next year to make way for a road.","opts":["will have it pulled","will be pulled","will pull","is pulling"],"a":1,"why":"Chủ ngữ là vật, “next year” là tương lai nên dùng will be + V3.","wrong":{"will have it pulled":"Cầu không phải người nhờ làm nên cấu trúc nhờ không hợp chủ ngữ “bridge”.","will pull":"Dạng chủ động nghĩa là cầu tự phá chính nó, trái với nghĩa của câu.","is pulling":"Dạng tiếp diễn chủ động không hợp vì cầu không thể tự phá."}},{"q":"The students ___ a certificate at the end of the course.","opts":["gave","were give","were giving","were given"],"a":3,"why":"Người nhận làm chủ ngữ với động từ hai tân ngữ: were given + tân ngữ trực tiếp.","wrong":{"gave":"Chủ động nghĩa là học sinh đi trao chứng chỉ, trái với nghĩa của câu.","were give":"Sau “were” phải dùng V3 “given”, không dùng nguyên mẫu.","were giving":"Dạng chủ động tiếp diễn sai vì học sinh là người nhận chứng chỉ."}},{"q":"She had her teeth ___ at the clinic last month.","opts":["checking","checked","to check","check"],"a":1,"why":"Have + vật + V3 nghĩa là nhờ người khác kiểm tra; “checked” là dạng đúng.","wrong":{"checking":"Sau “had + vật” cần V3, không dùng V-ing trong nghĩa nhờ làm.","to check":"Cấu trúc nhờ làm có V3 hoặc nguyên mẫu trần, không dùng “to check”.","check":"Nguyên mẫu trần sai nghĩa vì răng không tự kiểm tra, cần V3."}},{"q":"The contract ought ___ before the deadline.","opts":["to have been signed","to be signing","to have signed","having been signed"],"a":0,"why":"Việc lẽ ra phải làm trong quá khứ với chủ ngữ vật: ought to have been + V3.","wrong":{"to be signing":"Dạng chủ động tiếp diễn sai vì hợp đồng không tự ký.","to have signed":"Dạng chủ động hoàn thành sai vì hợp đồng là vật được ký.","having been signed":"Sau “ought” cần “to + nguyên mẫu”, không dùng dạng danh động từ."}},{"q":"Nobody wants ___ to a meeting they have no reason to attend.","opts":["inviting","been invited","to be invited","to invite"],"a":2,"why":"Sau “want” dùng nguyên mẫu bị động “to be + V3” vì chủ ngữ là người bị mời.","wrong":{"inviting":"Dạng chủ động nghĩa là họ đi mời người khác, trái với nghĩa của câu.","been invited":"Sau “wants” cần nguyên mẫu “to be”, không dùng V3 đứng một mình.","to invite":"Nguyên mẫu chủ động nghĩa là họ đi mời, không phải bị mời."}}]}},"prepositional-phrases":{"mistakes":[{"wrong":"She is in charge for the night shift.","right":"She is in charge of the night shift.","bad":"for","fix":"of","why":"Cụm cố định là “in charge of”. Người Việt hay dịch “phụ trách cho” nên chọn nhầm “for”."},{"wrong":"Despite of the rain, we went out.","right":"Despite the rain, we went out.","bad":"Despite of","fix":"Despite","why":"“Despite” không đi với “of”; chỉ “in spite of” mới có “of”. Hãy nhớ: despite = in spite of, bỏ “in” và “of”."},{"wrong":"There was a rise on the cost of housing.","right":"There was a rise in the cost of housing.","bad":"on","fix":"in","why":"Sau “a rise / an increase” nêu thứ thay đổi bằng “in”. “On” không phải giới từ đi kèm danh từ này."},{"wrong":"He went to work with car every day.","right":"He went to work by car every day.","bad":"with","fix":"by","why":"Phương tiện chung dùng “by + danh từ không mạo từ” như by car, by bus. “With” chỉ dùng cho dụng cụ."},{"wrong":"The delay was owing of the strike.","right":"The delay was owing to the strike.","bad":"of","fix":"to","why":"“Owing to” và “due to” đều đi với “to”. Chữ “of” làm bạn nghĩ tới “because of”, đây là bẫy hay gặp."},{"wrong":"We arrived on time to catch the train.","right":"We arrived in time to catch the train.","bad":"on","fix":"in","why":"“In time to + V” là kịp để làm gì; “on time” chỉ là đúng giờ theo lịch. Câu này nói kịp bắt tàu nên cần “in time”."},{"wrong":"The nurse is prone of headaches.","right":"The nurse is prone to headaches.","bad":"of","fix":"to","why":"“Prone”, “subject”, “liable” đi với “to”. Đừng dùng “of” theo thói quen của “aware of”, “afraid of”."},{"wrong":"At the end I decided to stay.","right":"In the end I decided to stay.","bad":"At","fix":"In","why":"“In the end” là rốt cuộc, một mình đứng đầu câu. “At the end” bắt buộc có “of + danh từ”, ví dụ at the end of the film."}],"contrast":{"title":"in time hay on time?","a":"in time","b":"on time","rows":[["Nghĩa","Kịp lúc, không muộn để làm việc gì: “in time to see him”.","Đúng giờ theo lịch hoặc giờ hẹn: “the train left on time”."],["Đi với gì","Thường có “for + danh từ” hoặc “to + V”: in time for dinner.","Đứng một mình hoặc sau động từ: arrive on time."],["So sánh trong ví dụ","Có thể đến sớm hơn lịch nhưng vẫn kịp: in time for the meeting.","Phải đúng giờ đã định, không sớm không muộn: on time for the meeting."],["Thành ngữ gần","just in time: vừa kịp, suýt muộn.","right on time: đúng giờ chính xác."]],"ex":[["We got to the station in time to buy a ticket.","The lecture started on time at nine."],["She was in time for the last bus.","The bus was on time, as usual."]],"tip":"In time = kịp làm một việc; on time = đúng theo lịch đã định.","quiz":[{"q":"The film starts at eight, so please be there ___.","opts":["on time","in time","at time","by time"],"a":0,"why":"Giờ chiếu phim đã định là 8 giờ, nên “on time” (đúng giờ theo lịch) là phù hợp.","wrong":{"in time":"“In time” nghĩa là kịp cho một việc khác; ở đây chỉ giờ chiếu cố định nên cần đúng giờ.","at time":"“At time” không là cụm cố định trong tiếng Anh nên không dùng được ở đây.","by time":"“By time” không tồn tại; “by the time” là liên từ đi với mệnh đề."}},{"q":"Luckily, the ambulance arrived ___ to save the child.","opts":["on time","in time","at time","by time"],"a":1,"why":"“In time to + V” nghĩa là kịp làm gì; “to save the child” cho thấy mục đích kịp lúc.","wrong":{"on time":"“On time” chỉ đúng giờ theo lịch; ở đây cần ý kịp lúc để cứu đứa trẻ.","at time":"“At time” không là cụm đúng, không diễn đạt nghĩa kịp lúc.","by time":"“By time” không tồn tại như cụm cố định trước “to + V”."}},{"q":"Our flight left ten minutes early, and we only got there ___ to board.","opts":["right on time","on time","just in time","at the time"],"a":2,"why":"“Just in time to + V” là vừa kịp; chuyến bay đi sớm 10 phút và “only got there” cho thấy suýt muộn.","wrong":{"right on time":"“Right on time” nghĩa là đúng giờ chính xác, trong khi chuyến bay đi sớm nên hành khách suýt trễ.","on time":"“On time” không hợp vì máy bay đã khởi hành sớm hơn lịch và ta chỉ vừa kịp.","at the time":"“At the time” nghĩa là vào lúc đó, không mang nghĩa kịp để lên máy bay."}},{"q":"The conference began promptly at nine, and all the speakers were ___.","opts":["in time","at time","by time","on time"],"a":3,"why":"“Promptly at nine” cho thấy lịch cố định, nên diễn giả có mặt “on time” (đúng giờ).","wrong":{"in time":"“In time” cần đi với “for/to” để chỉ kịp việc gì; ở đây chỉ nói diễn giả có mặt đúng giờ.","at time":"“At time” không có nghĩa này trong tiếng Anh chuẩn.","by time":"“By time” không phải cụm cố định để nói đúng giờ."}},{"q":"The study found that children from poorer families are more ___ risk of obesity.","opts":["in","at","on","under"],"a":1,"why":"“At risk of + danh từ” nghĩa là có nguy cơ; “more … risk of obesity” cho thấy cụm này.","wrong":{"in":"“In risk” sai; để nói có nguy cơ phải dùng cụm cố định “at risk of”.","on":"“On risk” không phải cụm cố định và không mang nghĩa có nguy cơ.","under":"“Under risk” không dùng; “under” chỉ hợp với cụm như under pressure."}},{"q":"The new regulations apply to all employees, ___ the managers.","opts":["including","instead of","apart from","owing to"],"a":0,"why":"Câu nói quy định áp dụng cho tất cả nhân viên và còn cả quản lý nên chọn “including”; ý nhấn mạnh “all”.","wrong":{"instead of":"“Instead of” nghĩa là thay vì và loại managers ra, trái với ý áp dụng cho tất cả.","apart from":"“Apart from” có thể mang nghĩa trừ ra, nên câu sẽ thành quy định không áp dụng cho quản lý, đổi nghĩa so với ngữ cảnh.","owing to":"“Owing to” chỉ nguyên nhân, không nối được danh sách đối tượng áp dụng quy định."}},{"q":"Please complete the form ___ means of the online portal.","opts":["with","in","by","through"],"a":2,"why":"“By means of + danh từ” nghĩa là bằng phương tiện; “online portal” là công cụ hoàn thành mẫu đơn.","wrong":{"with":"“With means of” không phải cụm cố định; “by means of” mới nghĩa là bằng cách.","in":"“In means of” không tồn tại; cụm giới từ đúng bắt đầu bằng “by”.","through":"“Through means of” không dùng trong tiếng Anh chuẩn; cụm cố định là “by means of”."}},{"q":"The flight was delayed ___ fog, so we missed the connection.","opts":["in spite of","instead of","apart from","due to"],"a":3,"why":"“Due to + danh từ” đứng sau “was delayed” chỉ nguyên nhân; “so we missed the connection” xác nhận kết quả xấu.","wrong":{"in spite of":"“In spite of” nghĩa là bất chấp; sương mù là nguyên nhân gây trễ chứ không bị bỏ qua.","instead of":"“Instead of” nghĩa là thay vì, không chỉ nguyên nhân của việc chuyến bay bị hoãn.","apart from":"“Apart from” nghĩa là ngoài ra; không nối được nguyên nhân là sương mù với việc bị trễ."}}]}},"verb-patterns-advanced":{"mistakes":[{"wrong":"He denied to steal the money.","right":"He denied stealing the money.","bad":"to steal","fix":"stealing","why":"Deny luôn đi với V-ing. Người Việt hay dùng “to V” vì nghĩ động từ nào cũng giống “muốn làm gì”."},{"wrong":"They made me to wait outside.","right":"They made me wait outside.","bad":"to wait","fix":"wait","why":"Make + tân ngữ + V nguyên mẫu không “to” (chỉ thêm “to” ở dạng bị động “I was made to wait”)."},{"wrong":"I stopped to smoke last year.","right":"I stopped smoking last year.","bad":"to smoke","fix":"smoking","why":"“Stop to smoke” là dừng lại để hút thuốc; bỏ hẳn thói quen thì dùng “stop + V-ing”."},{"wrong":"I spent three hours to clean the lab.","right":"I spent three hours cleaning the lab.","bad":"to clean","fix":"cleaning","why":"Spend + thời gian + V-ing, đừng dịch “để làm gì” thành “to V” như trong tiếng Việt."},{"wrong":"This shirt needs to wash.","right":"This shirt needs washing.","bad":"to wash","fix":"washing","why":"Chiếc áo không tự giặt, nên dùng “needs washing” hoặc “needs to be washed”, nghĩa bị động."},{"wrong":"I remember to meet him at a party years ago.","right":"I remember meeting him at a party years ago.","bad":"to meet","fix":"meeting","why":"Nhớ lại việc đã xảy ra dùng remember + V-ing; “to V” chỉ nhớ để làm việc sắp tới."},{"wrong":"I heard someone to knock at the door.","right":"I heard someone knock at the door.","bad":"to knock","fix":"knock","why":"Sau động từ tri giác + tân ngữ không dùng “to”; dùng V nguyên mẫu hoặc V-ing."},{"wrong":"She hates asked questions about her age.","right":"She hates being asked questions about her age.","bad":"","fix":"being","why":"Sau hate, cần dạng bị động “being asked”; chỉ dùng quá khứ phân từ trơn là thiếu “being”."}],"contrast":{"title":"remember + V-ing hay remember + to V?","a":"remember / forget / stop + V-ing","b":"remember / forget / stop + to V","rows":[["Thời điểm của việc","Việc đã xảy ra rồi: “I remember locking it”.","Việc chưa xảy ra, sắp làm: “Remember to lock it”."],["Nghĩa của stop","Ngừng hẳn hành động: “He stopped smoking”.","Dừng lại để làm việc khác: “He stopped to smoke”."],["Forget","Quên một kỷ niệm đã trải qua: “I'll never forget seeing it”.","Quên không làm việc cần làm: “I forgot to call her”."],["Regret","Hối tiếc việc đã làm: “I regret saying that”.","Tiếc nuối khi báo tin: “We regret to inform you”."]],"ex":[["I stopped talking when the doctor came in.","I stopped to talk to the doctor on my way out."],["She remembered locking the door, so she did not go back.","She remembered to lock the door before she left."]],"tip":"V-ing nhìn về quá khứ hoặc việc đang làm; to V hướng về mục đích và việc sắp làm.","quiz":[{"t":"c","q":"I'm sure I locked the door. I clearly remember ___ it.","opts":["locking","to lock","lock","to have locked"],"a":0,"why":"Câu nói về ký ức việc đã làm (“I'm sure I locked”), nên dùng remember + V-ing.","wrong":{"to lock":"“Remember to lock” là nhớ phải khóa, còn người nói đã chắc chắn khóa rồi.","lock":"V nguyên mẫu trần không đi sau remember trong câu này.","to have locked":"Dạng này nghe nặng nề, V-ing đơn giản đã đủ để nói về ký ức."}},{"t":"c","q":"It's cold in the lab. Remember ___ your coat when you come tomorrow.","opts":["bringing","to bring","bring","having brought"],"a":1,"why":"“Tomorrow” cho thấy việc mang áo chưa xảy ra, nên dùng remember + to V.","wrong":{"bringing":"V-ing nói về ký ức đã qua, nhưng lời nhắc này nói về việc sắp làm vào ngày mai.","bring":"V nguyên mẫu trần không đi sau remember trong lời nhắc nhở.","having brought":"Dạng hoàn thành chỉ việc đã xong, trái với “tomorrow” trong câu."}},{"t":"c","q":"He has a bad cough, so the doctor told him to stop ___.","opts":["to smoke","to be smoking","smoking","smoke"],"a":2,"why":"Bác sĩ muốn anh ấy bỏ hẳn thói quen xấu, nên dùng stop + V-ing.","wrong":{"to smoke":"“Stop to smoke” nghĩa là dừng lại để hút thuốc, trái với lời bác sĩ khuyên.","to be smoking":"Dạng này không đi sau stop để chỉ việc bỏ thói quen.","smoke":"V nguyên mẫu trần không đi sau stop trong câu này."}},{"t":"c","q":"We were driving to the airport when we stopped ___ petrol.","opts":["buying","buy","having bought","to buy"],"a":3,"why":"Họ đang lái xe và dừng lại với mục đích mua xăng, nên dùng stop + to V.","wrong":{"buying":"“Stop buying” nghĩa là ngừng mua, trong khi họ dừng xe để mua xăng.","buy":"V nguyên mẫu trần không đi sau stop; cần “to V” chỉ mục đích.","having bought":"Dạng hoàn thành không diễn tả mục đích của việc dừng lại."}},{"t":"c","q":"We regret ___ you that the flight has been cancelled.","opts":["to inform","informing","inform","having inform"],"a":0,"why":"“Regret to inform” là cụm cố định khi thông báo tin xấu ngay lúc nói.","wrong":{"informing":"“Regret informing” nghĩa là hối tiếc vì đã thông báo, không phải thông báo tin xấu.","inform":"V nguyên mẫu trần không đi sau regret trong thông báo trang trọng.","having inform":"Dạng này sai hình thức vì thiếu quá khứ phân từ sau having."}},{"t":"c","q":"I regret ___ so rudely to her; I should have apologised at once.","opts":["to speak","speaking","speak","to have been speaking"],"a":1,"why":"“I should have apologised” cho thấy việc nói thô lỗ đã xảy ra, nên dùng regret + V-ing.","wrong":{"to speak":"“Regret to speak” nghĩa là tiếc phải nói bây giờ, không phải tiếc vì đã nói.","speak":"V nguyên mẫu trần không đi sau regret ở câu này.","to have been speaking":"Dạng tiếp diễn hoàn thành không đi sau regret và làm câu rối nghĩa."}},{"t":"c","q":"She tried ___ the recipe with less sugar, and it tasted much better.","opts":["to use","use","using","to be using"],"a":2,"why":"Việc thử rồi nếm thấy ngon hơn là thử nghiệm một cách làm, nên dùng try + V-ing.","wrong":{"to use":"“Try to use” là cố gắng dùng, còn ở đây cô thử một cách làm và có kết quả.","use":"V nguyên mẫu trần không đi sau try trong nghĩa thử nghiệm.","to be using":"Dạng tiếp diễn nguyên mẫu không dùng sau try trong câu này."}},{"t":"c","q":"The software kept crashing. He tried ___ it, but nothing worked.","opts":["fixing","fix","having fixed","to fix"],"a":3,"why":"“Nothing worked” cho thấy anh ấy cố sửa nhưng không thành, nên dùng try + to V.","wrong":{"fixing":"“Try fixing” là thử một cách sửa, nhưng “nothing worked” nghiêng về cố gắng không thành công.","fix":"V nguyên mẫu trần không đi sau try trong câu này.","having fixed":"Dạng hoàn thành nghĩa là đã sửa xong, trái với “nothing worked”."}}]}}};
  const ORDER = [["third-conditional","modals-past","past-perfect-continuous","reporting-verbs","relative-nondefining","passive-reporting","linking","comparison-advanced","indirect-questions","articles-advanced","adjective-gradability","causative","future-perfect","subjunctive-formal"],["mixed-conditionals","inversion","participle-clauses","cleft-sentences","adverbial-clauses","nominalisation","ellipsis-substitution","hedging-modality","discourse-markers","complex-noun-phrases","verb-patterns-advanced","modals-advanced","passive-advanced","emphasis-structures","prepositional-phrases"]];
  const UNITMAP = {"modals-advanced":"c1-01","emphasis-structures":"c1-02","complex-noun-phrases":"c1-03","verb-patterns-advanced":"c1-04","passive-advanced":"c1-06","prepositional-phrases":"c1-07"};
  NEW.forEach(g => GRAMMAR.push(g));
  Object.assign(GRAMMAR_BANK, BANK); Object.assign(GRAMMAR_THEORY, THEORY); Object.assign(GRAMMAR_GX, GX_ADD);
  const rank = Object.fromEntries(ORDER.flatMap(l => l.map((id, i) => [id, i])));
  const lv = { A1: 1, A2: 2, B1: 3, B2: 4, C1: 5 };
  GRAMMAR.sort((a, b) => (lv[a.lvl] - lv[b.lvl]) || ((rank[a.id] ?? 99) - (rank[b.id] ?? 99)));
  Object.entries(UNITMAP).forEach(([gid, uid]) => { const u = UNITS.find(x => x.id === uid); if (u && !u.grammar.includes(gid)) u.grammar.push(gid); });
})();
